package com.runedm;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

public class MessageStoreTest
{
	@Test
	public void persistsMessagesAndReadState() throws Exception
	{
		Path temporary = Files.createTempDirectory("runedm-test-");
		MessageStore store = new MessageStore(new Gson(), temporary);
		try
		{
			DmMessage first = DmMessage.create("A Friend", "hello", 1_700_000_000_000L, false);
			DmMessage second = DmMessage.create("A Friend", "hey", 1_700_000_001_000L, true);
			store.append(42L, first).get(5, TimeUnit.SECONDS);
			store.append(42L, second).get(5, TimeUnit.SECONDS);

			Map<String, Long> read = new HashMap<>();
			read.put("a friend", first.getTimestamp());
			store.saveReadState(42L, read).get(5, TimeUnit.SECONDS);

			LoadedHistory loaded = store.load(42L).get(5, TimeUnit.SECONDS);
			assertEquals(2, loaded.getMessages().size());
			assertEquals("hello", loaded.getMessages().get(0).getBody());
			assertEquals(Long.valueOf(first.getTimestamp()), loaded.getReadThrough().get("a friend"));
			assertTrue(Files.isRegularFile(store.accountDirectory(42L).resolve("messages.jsonl")));
		}
		finally
		{
			store.close();
		}
	}

	@Test
	public void atomicallyReplacesHistoryAfterDeletion() throws Exception
	{
		Path temporary = Files.createTempDirectory("runedm-rewrite-test-");
		MessageStore store = new MessageStore(new Gson(), temporary);
		try
		{
			DmMessage first = DmMessage.create("A Friend", "keep", 1_700_000_000_000L, false);
			DmMessage second = DmMessage.create("A Friend", "delete", 1_700_000_001_000L, true);
			store.append(42L, first).get(5, TimeUnit.SECONDS);
			store.append(42L, second).get(5, TimeUnit.SECONDS);
			store.replaceMessages(42L, Collections.singletonList(first)).get(5, TimeUnit.SECONDS);

			LoadedHistory loaded = store.load(42L).get(5, TimeUnit.SECONDS);
			assertEquals(1, loaded.getMessages().size());
			assertEquals("keep", loaded.getMessages().get(0).getBody());
		}
		finally
		{
			store.close();
		}
	}
}

