package com.runedm;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

public class DmRepositoryTest
{
	@Test
	public void deletesOneMessageOrAWholeConversationPersistently() throws Exception
	{
		Path temporary = Files.createTempDirectory("runedm-delete-test-");
		MessageStore store = new MessageStore(new Gson(), temporary);
		try
		{
			DmRepository repository = new DmRepository(store);
			repository.activate(42L, "Self");
			DmMessage kept = DmMessage.create("First Friend", "keep", 1_700_000_000_000L, false, 1L);
			DmMessage removed = DmMessage.create("First Friend", "remove", 1_700_000_001_000L, true, 2L);
			DmMessage otherChat = DmMessage.create("Second Friend", "remove chat", 1_700_000_002_000L, false, 3L);
			assertTrue(repository.addMessage(kept));
			assertTrue(repository.addMessage(removed));
			assertTrue(repository.addMessage(otherChat));

			assertTrue(repository.deleteMessage(removed.getPartnerKey(), removed.getId()));
			assertTrue(repository.deleteConversation(otherChat.getPartnerKey()));
			assertEquals(1, repository.getMessages(kept.getPartnerKey()).size());
			assertEquals(1, repository.getConversationSummaries("").size());

			LoadedHistory persisted = store.load(42L).get(5, TimeUnit.SECONDS);
			assertEquals(1, persisted.getMessages().size());
			assertEquals("keep", persisted.getMessages().get(0).getBody());
		}
		finally
		{
			store.close();
		}
	}
}

