package com.runedm;

import java.awt.image.BufferedImage;
import org.junit.Assert;
import org.junit.Test;

public class UiImagesTest
{
	@Test
	public void navigationIconFollowsTheSelectedTheme()
	{
		BufferedImage modern = UiImages.navigationIcon(RuneDmStyle.MODERN);
		BufferedImage osrs = UiImages.navigationIcon(RuneDmStyle.OSRS);
		Assert.assertEquals(32, modern.getWidth());
		Assert.assertEquals(32, osrs.getWidth());
		Assert.assertNotEquals(modern.getRGB(16, 10), osrs.getRGB(16, 10));
	}

	@Test
	public void everyEmojiChoiceHasBundledArtwork()
	{
		for (DmEmoji.Choice choice : DmEmoji.choices())
		{
			BufferedImage icon = UiImages.emojiIcon(choice, 20);
			Assert.assertEquals(choice.getName(), 20, icon.getWidth());
			Assert.assertEquals(choice.getName(), 20, icon.getHeight());
			boolean hasVisiblePixel = false;
			for (int y = 0; y < icon.getHeight() && !hasVisiblePixel; y++)
			{
				for (int x = 0; x < icon.getWidth(); x++)
				{
					if ((icon.getRGB(x, y) >>> 24) != 0)
					{
						hasVisiblePixel = true;
						break;
					}
				}
			}
			Assert.assertTrue(choice.getName(), hasVisiblePixel);
		}
	}
}

