public class RuneDmPanelTest
{
	@Test
	public void streamerModeConcealsInboxMessageText()
	{
		ConversationSummary summary = new ConversationSummary(
			"friend",
			"A Friend",
			"private raid plan :)",
			1_700_000_000_000L,
			1,
			true);

		assertEquals("Preview hidden", RuneDmPanel.inboxPreviewText(summary, true));
		String normal = RuneDmPanel.inboxPreviewText(summary, false);
		assertTrue(normal.startsWith("You: private raid plan"));
		assertFalse(RuneDmPanel.inboxPreviewText(summary, true).contains("raid plan"));
	}

	@Test
	public void messageTimestampIncludesMonthDayAndTime()
	{
		ZoneId zone = ZoneId.of("UTC");
		long timestamp = ZonedDateTime.of(2026, 9, 5, 2, 19, 0, 0, zone)
			.toInstant()
			.toEpochMilli();
		java.time.Instant now = ZonedDateTime.of(2026, 9, 6, 12, 0, 0, 0, zone).toInstant();

		assertEquals("Sep 5 • 2:19 AM", RuneDmPanel.formatMessageTimestamp(timestamp, now, zone));
	}

	@Test
	public void messageTimestampAddsYearOnlyAfterOneYear()
	{
		ZoneId zone = ZoneId.of("UTC");
		java.time.Instant now = ZonedDateTime.of(2026, 9, 6, 12, 0, 0, 0, zone).toInstant();
		long exactlyOneYear = ZonedDateTime.of(2025, 9, 6, 12, 0, 0, 0, zone).toInstant().toEpochMilli();
		long older = ZonedDateTime.of(2025, 9, 5, 2, 19, 0, 0, zone).toInstant().toEpochMilli();

		assertEquals("Sep 6 • 12:00 PM", RuneDmPanel.formatMessageTimestamp(exactlyOneYear, now, zone));
		assertEquals("Sep 5, 2025 • 2:19 AM", RuneDmPanel.formatMessageTimestamp(older, now, zone));
		assertEquals("Sep 6", RuneDmPanel.formatListTime(exactlyOneYear, now, zone));
		assertEquals("Sep 5, 2025", RuneDmPanel.formatListTime(older, now, zone));
	}

	@Test
	public void pageStatusLabelsFillTheRowAndAlignLeft()
	{
		JPanel column = new JPanel();
		column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
		JButton fullWidthButton = new JButton("New message");
		fullWidthButton.setAlignmentX(Component.CENTER_ALIGNMENT);
		fullWidthButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
		JLabel status = new JLabel("Hopping to World 603...");

		RuneDmPanel.configurePageStatusLabel(status);
		column.add(fullWidthButton);
		column.add(status);
		column.setSize(220, 60);
		column.doLayout();

		assertEquals(SwingConstants.LEFT, status.getHorizontalAlignment());
		assertEquals(Component.CENTER_ALIGNMENT, status.getAlignmentX(), 0.0f);
		assertEquals(Integer.MAX_VALUE, status.getMaximumSize().width);
		assertTrue(status.getMaximumSize().height > 0);
		assertEquals(0, status.getX());
		assertEquals(220, status.getWidth());
	}

	@Test
	public void osrsIsTheDefaultSelectableStyle()
	{
		RuneDmConfig config = new RuneDmConfig() { };
		assertEquals(RuneDmStyle.OSRS, config.interfaceStyle());
		assertEquals("Modern", RuneDmStyle.MODERN.toString());
		assertEquals("OSRS", RuneDmStyle.OSRS.toString());
		assertEquals("Varlamore Sunset", RuneDmStyle.VARLAMORE_SUNSET.toString());
		assertEquals("Morytania Night", RuneDmStyle.MORYTANIA_NIGHT.toString());
		assertEquals("Prifddinas Crystal", RuneDmStyle.PRIFDDINAS_CRYSTAL.toString());
		assertEquals("Lumbridge", RuneDmStyle.LUMBRIDGE.toString());
		assertEquals("Varrock", RuneDmStyle.VARROCK.toString());
	}

	@Test
	public void themesUseColorOnlyPalettes()
	{
		assertEquals(new Color(255, 152, 31), RuneDmStyle.OSRS.accent);
		assertTrue(RuneDmStyle.OSRS.beveled);
		assertFalse(RuneDmStyle.OSRS.wallpaperBackdrop);
		assertFalse(RuneDmStyle.VARLAMORE_SUNSET.wallpaperBackdrop);
		assertFalse(RuneDmStyle.MORYTANIA_NIGHT.wallpaperBackdrop);
		assertFalse(RuneDmStyle.PRIFDDINAS_CRYSTAL.wallpaperBackdrop);
		assertFalse(RuneDmStyle.LUMBRIDGE.wallpaperBackdrop);
		assertFalse(RuneDmStyle.VARROCK.wallpaperBackdrop);
		assertFalse(RuneDmStyle.MODERN.beveled);
	}

	@Test
	public void noThemeBundlesThirdPartyScenery()
	{
		for (RuneDmStyle style : RuneDmStyle.values())
		{
			if (style.wallpaperBackdrop)
			{
				assertTrue(style.wallpaperResource != null);
				assertTrue(ThemeBackgrounds.forStyle(style) != null);
				assertTrue(ThemeBackgrounds.forStyle(style).getWidth() >= 700);
				assertTrue(ThemeBackgrounds.forStyle(style).getHeight() >= 450);
			}
			else
			{
				assertNull(style.wallpaperResource);
				assertNull(ThemeBackgrounds.forStyle(style));
			}
		}
	}

	@Test
	public void locationSceneUsesCoverCropWithoutStretching()
	{
		Rectangle bounds = RuneDmPanel.coverBounds(750, 500, 240, 620);
		assertEquals(620, bounds.height);
		assertEquals(0, bounds.y);
		assertTrue(bounds.width > 240);
		assertTrue(bounds.x < 0);
	}

	@Test
	public void conversationTextUsesTheLargerInGameRuneScapeFont()
	{
		ChatText message = new ChatText("Hello :) adventurer", Font.PLAIN,
			RuneDmPanel.MESSAGE_FONT_SIZE, Color.WHITE, 186);
		assertEquals(ChatText.runescapeChatFont(Font.PLAIN, RuneDmPanel.MESSAGE_FONT_SIZE).getFontName(),
			message.getFont().getFontName());
		assertEquals(18f, message.getFont().getSize2D(), 0.0f);
		assertTrue(message.getPreferredSize().width > 0);
		assertTrue(message.getPreferredSize().width <= 186);
		assertTrue(message.getPreferredSize().height > 0);
	}

	@Test
	public void homepageAndConversationUseReadableFontFloors()
	{
		assertTrue(RuneDmPanel.INBOX_TITLE_FONT_SIZE >= 20f);
		assertTrue(RuneDmPanel.INBOX_NAME_FONT_SIZE >= 14f);
		assertTrue(RuneDmPanel.INBOX_PREVIEW_FONT_SIZE >= 13f);
		assertTrue(RuneDmPanel.INBOX_TIMESTAMP_FONT_SIZE >= 11f);
		assertTrue(RuneDmPanel.MESSAGE_FONT_SIZE >= 18f);
		assertTrue(RuneDmPanel.MESSAGE_TIMESTAMP_FONT_SIZE >= 13f);
	}
}

