package com.runedm;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.EnumMap;
import java.util.Map;
import javax.imageio.ImageIO;

/** Loads an optional bundled background once for reuse across sidebar repaints. */
final class ThemeBackgrounds
{
	private static final Map<RuneDmStyle, BufferedImage> IMAGES = loadImages();

	private ThemeBackgrounds()
	{
	}

	static BufferedImage forStyle(RuneDmStyle style)
	{
		return style == null ? null : IMAGES.get(style);
	}

	private static Map<RuneDmStyle, BufferedImage> loadImages()
	{
		Map<RuneDmStyle, BufferedImage> images = new EnumMap<>(RuneDmStyle.class);
		for (RuneDmStyle style : RuneDmStyle.values())
		{
			if (style.wallpaperResource == null)
			{
				continue;
			}

			try (InputStream stream = ThemeBackgrounds.class.getResourceAsStream(style.wallpaperResource))
			{
				if (stream != null)
				{
					BufferedImage image = ImageIO.read(stream);
					if (image != null)
					{
						images.put(style, image);
					}
				}
			}
			catch (IOException ignored)
			{
				// RuneDmPanel retains its palette-gradient fallback if an asset cannot load.
			}
		}
		return images;
	}
}

