package com.runedm;

import java.util.Objects;

final class FriendPresence
{
	private final String displayName;
	private final String playerKey;
	private final int world;

	FriendPresence(String displayName, int world)
	{
		this.displayName = NameTools.displayName(displayName);
		this.playerKey = NameTools.normalize(this.displayName);
		this.world = Math.max(0, world);
	}

	String getDisplayName()
	{
		return displayName;
	}

	String getPlayerKey()
	{
		return playerKey;
	}

	int getWorld()
	{
		return world;
	}

	boolean isOnline()
	{
		return world > 0;
	}

	boolean isValid()
	{
		return !playerKey.isEmpty();
	}

	@Override
	public boolean equals(Object object)
	{
		if (this == object)
		{
			return true;
		}
		if (!(object instanceof FriendPresence))
		{
			return false;
		}
		FriendPresence other = (FriendPresence) object;
		return world == other.world
			&& displayName.equals(other.displayName)
			&& playerKey.equals(other.playerKey);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(displayName, playerKey, world);
	}
}

