package com.runedm;

final class DmMessage
{
	private String id;
	private String partnerKey;
	private String partnerName;
	private String body;
	private long timestamp;
	private boolean outgoing;

	@SuppressWarnings("unused")
	private DmMessage()
	{
		// Gson constructor.
	}

	private DmMessage(String partnerName, String body, long timestamp, boolean outgoing)
	{
		this(partnerName, body, timestamp, outgoing, 0L);
	}

	private DmMessage(String partnerName, String body, long timestamp, boolean outgoing, long sourceId)
	{
		this.partnerName = NameTools.displayName(partnerName);
		this.partnerKey = NameTools.normalize(partnerName);
		this.body = body;
		this.timestamp = timestamp;
		this.outgoing = outgoing;
		this.id = NameTools.messageId(partnerKey, outgoing, body, timestamp, sourceId);
	}

	static DmMessage create(String partnerName, String body, long timestamp, boolean outgoing)
	{
		return new DmMessage(partnerName, body, timestamp, outgoing);
	}

	static DmMessage create(String partnerName, String body, long timestamp, boolean outgoing, long sourceId)
	{
		return new DmMessage(partnerName, body, timestamp, outgoing, sourceId);
	}

	boolean isValid()
	{
		return id != null && !id.isEmpty()
			&& partnerKey != null && !partnerKey.isEmpty()
			&& partnerName != null && !partnerName.isEmpty()
			&& body != null && !body.isEmpty()
			&& timestamp > 0L;
	}

	String getId()
	{
		return id;
	}

	String getPartnerKey()
	{
		return partnerKey;
	}

	String getPartnerName()
	{
		return partnerName;
	}

	String getBody()
	{
		return body;
	}

	long getTimestamp()
	{
		return timestamp;
	}

	boolean isOutgoing()
	{
		return outgoing;
	}
}

