package com.runedm;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;

final class DmRepository
{
	interface Listener
	{
		void onHistoryChanged();
	}

	private final MessageStore store;
	private final Map<String, List<DmMessage>> conversations = new HashMap<>();
	private final Map<String, Long> readThrough = new HashMap<>();
	private final Set<String> messageIds = new HashSet<>();
	private final List<Listener> listeners = new CopyOnWriteArrayList<>();

	private long accountHash;
	private String selfName = "";
	private int generation;
	private boolean active;

	DmRepository(MessageStore store)
	{
		this.store = store;
	}

	void addListener(Listener listener)
	{
		listeners.add(listener);
	}

	void removeListener(Listener listener)
	{
		listeners.remove(listener);
	}

	void activate(long newAccountHash, String newSelfName)
	{
		final int loadGeneration;
		synchronized (this)
		{
			if (active && accountHash == newAccountHash)
			{
				selfName = NameTools.displayName(newSelfName);
				return;
			}

			generation++;
			loadGeneration = generation;
			active = true;
			accountHash = newAccountHash;
			selfName = NameTools.displayName(newSelfName);
			conversations.clear();
			readThrough.clear();
			messageIds.clear();
		}
		notifyListeners();

		store.load(newAccountHash).thenAccept(loaded ->
		{
			synchronized (DmRepository.this)
			{
				if (!active || generation != loadGeneration || accountHash != newAccountHash)
				{
					return;
				}

				for (DmMessage message : loaded.getMessages())
				{
					addToMemory(message);
				}
				loaded.getReadThrough().forEach((key, value) -> readThrough.merge(key, value, Math::max));
			}
			notifyListeners();
		});
	}

	void deactivate()
	{
		synchronized (this)
		{
			generation++;
			active = false;
			accountHash = 0L;
			selfName = "";
			conversations.clear();
			readThrough.clear();
			messageIds.clear();
		}
		notifyListeners();
	}

	boolean addMessage(DmMessage message)
	{
		long account;
		synchronized (this)
		{
			if (!active || !addToMemory(message))
			{
				return false;
			}
			account = accountHash;
		}

		store.append(account, message);
		notifyListeners();
		return true;
	}

	private boolean addToMemory(DmMessage message)
	{
		if (message == null || !message.isValid() || !messageIds.add(message.getId()))
		{
			return false;
		}

		List<DmMessage> messages = conversations.computeIfAbsent(message.getPartnerKey(), ignored -> new ArrayList<>());
		messages.add(message);
		messages.sort(Comparator.comparingLong(DmMessage::getTimestamp).thenComparing(DmMessage::getId));
		return true;
	}

	void markRead(String partnerKey)
	{
		long account;
		Map<String, Long> snapshot;
		synchronized (this)
		{
			List<DmMessage> messages = conversations.get(partnerKey);
			if (!active || messages == null || messages.isEmpty())
			{
				return;
			}

			long newest = messages.get(messages.size() - 1).getTimestamp();
			long previous = readThrough.getOrDefault(partnerKey, 0L);
			if (newest <= previous)
			{
				return;
			}
			readThrough.put(partnerKey, newest);
			account = accountHash;
			snapshot = new HashMap<>(readThrough);
		}

		store.saveReadState(account, snapshot);
		notifyListeners();
	}

	boolean deleteMessage(String partnerKey, String messageId)
	{
		long account;
		List<DmMessage> snapshot;
		Map<String, Long> readSnapshot = null;
		synchronized (this)
		{
			if (!active || partnerKey == null || messageId == null)
			{
				return false;
			}
			List<DmMessage> messages = conversations.get(partnerKey);
			if (messages == null)
			{
				return false;
			}

			DmMessage removed = null;
			for (DmMessage message : messages)
			{
				if (messageId.equals(message.getId()))
				{
					removed = message;
					break;
				}
			}
			if (removed == null)
			{
				return false;
			}

			messages.remove(removed);
			messageIds.remove(removed.getId());
			if (messages.isEmpty())
			{
				conversations.remove(partnerKey);
				if (readThrough.remove(partnerKey) != null)
				{
					readSnapshot = new HashMap<>(readThrough);
				}
			}
			account = accountHash;
			snapshot = snapshotMessages();
		}

		store.replaceMessages(account, snapshot);
		if (readSnapshot != null)
		{
			store.saveReadState(account, readSnapshot);
		}
		notifyListeners();
		return true;
	}

	boolean deleteConversation(String partnerKey)
	{
		long account;
		List<DmMessage> snapshot;
		Map<String, Long> readSnapshot;
		synchronized (this)
		{
			if (!active || partnerKey == null)
			{
				return false;
			}
			List<DmMessage> removed = conversations.remove(partnerKey);
			if (removed == null || removed.isEmpty())
			{
				return false;
			}
			for (DmMessage message : removed)
			{
				messageIds.remove(message.getId());
			}
			readThrough.remove(partnerKey);
			account = accountHash;
			snapshot = snapshotMessages();
			readSnapshot = new HashMap<>(readThrough);
		}

		store.replaceMessages(account, snapshot);
		store.saveReadState(account, readSnapshot);
		notifyListeners();
		return true;
	}

	private List<DmMessage> snapshotMessages()
	{
		List<DmMessage> snapshot = new ArrayList<>();
		for (List<DmMessage> messages : conversations.values())
		{
			snapshot.addAll(messages);
		}
		snapshot.sort(Comparator.comparingLong(DmMessage::getTimestamp).thenComparing(DmMessage::getId));
		return snapshot;
	}

	synchronized List<ConversationSummary> getConversationSummaries(String filter)
	{
		String normalizedFilter = filter == null ? "" : filter.trim().toLowerCase(Locale.ROOT);
		List<ConversationSummary> summaries = new ArrayList<>();
		for (Map.Entry<String, List<DmMessage>> entry : conversations.entrySet())
		{
			List<DmMessage> messages = entry.getValue();
			if (messages.isEmpty())
			{
				continue;
			}

			DmMessage latest = messages.get(messages.size() - 1);
			if (!normalizedFilter.isEmpty()
				&& !latest.getPartnerName().toLowerCase(Locale.ROOT).contains(normalizedFilter)
				&& !latest.getBody().toLowerCase(Locale.ROOT).contains(normalizedFilter))
			{
				continue;
			}

			long readTimestamp = readThrough.getOrDefault(entry.getKey(), 0L);
			int unread = 0;
			for (DmMessage message : messages)
			{
				if (!message.isOutgoing() && message.getTimestamp() > readTimestamp)
				{
					unread++;
				}
			}

			summaries.add(new ConversationSummary(
				entry.getKey(),
				latest.getPartnerName(),
				latest.getBody(),
				latest.getTimestamp(),
				unread,
				latest.isOutgoing()));
		}

		summaries.sort(Comparator.comparingLong(ConversationSummary::getLastTimestamp).reversed());
		return summaries;
	}

	synchronized List<DmMessage> getMessages(String partnerKey)
	{
		List<DmMessage> messages = conversations.get(partnerKey);
		return messages == null ? new ArrayList<>() : new ArrayList<>(messages);
	}

	synchronized int getTotalUnread()
	{
		int total = 0;
		for (ConversationSummary summary : getConversationSummaries(""))
		{
			total += summary.getUnreadCount();
		}
		return total;
	}

	synchronized boolean isActive()
	{
		return active;
	}

	synchronized long getAccountHash()
	{
		return accountHash;
	}

	synchronized String getSelfName()
	{
		return selfName;
	}

	private void notifyListeners()
	{
		for (Listener listener : listeners)
		{
			listener.onHistoryChanged();
		}
	}
}

