	private JPopupMenu friendPopupMenu(String friendName, Integer friendWorld, Runnable deleteAction)
	{
		JPopupMenu popup = styledPopupMenu();
		JMenuItem runeProfile = menuItem("RuneProfile");
		runeProfile.addActionListener(event -> openRuneProfile(friendName));
		popup.add(runeProfile);
		if (friendWorld != null && friendWorld > 0)
		{
			popup.addSeparator();
			JMenuItem hop = menuItem(friendWorld == selfWorld
				? "Already on World " + friendWorld
				: "Hop to World " + friendWorld);
			hop.setEnabled(friendWorld != selfWorld);
			hop.addActionListener(event -> requestWorldHop(friendName, friendWorld));
			popup.add(hop);
		}
		if (deleteAction != null)
		{
			if (popup.getComponentCount() > 0)
			{
				popup.addSeparator();
			}
			JMenuItem delete = menuItem("Delete chat history");
			delete.addActionListener(event -> deleteAction.run());
			popup.add(delete);
		}
		return popup;
	}

	private void openRuneProfile(String friendName)
	{
		okhttp3.HttpUrl url = AvatarService.runeProfilePageUrl(friendName);
		if (url != null)
		{
			LinkBrowser.browse(url.toString());
