	private void requestWorldHop(String friendName, int world)
	{
		setTemporaryContextStatus("Opening World " + world + " for " + friendName + "...");
		actions.hopToWorld(world, (success, status) ->
			SwingUtilities.invokeLater(() -> setTemporaryContextStatus(status)));
