	private void deleteMessage(DmMessage message)
	{
		int choice = JOptionPane.showConfirmDialog(
			this,
			"Delete this saved message? This cannot be undone.",
			"Delete message",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE);
		if (choice != JOptionPane.YES_OPTION)
		{
			return;
		}

		if (repository.deleteMessage(message.getPartnerKey(), message.getId()))
		{
			setStatus("Message deleted.");
		}
		else
		{
			setStatus("That message could not be deleted.");
		}
	}

	private void deleteConversation(ConversationSummary summary)
	{
		int choice = JOptionPane.showConfirmDialog(
			this,
			"Delete all saved messages with " + summary.getPartnerName() + "? This cannot be undone.",
			"Delete chat history",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE);
		if (choice != JOptionPane.YES_OPTION)
		{
			return;
		}

		setInboxStatus(repository.deleteConversation(summary.getPartnerKey())
			? "Chat history with " + summary.getPartnerName() + " deleted."
			: "That chat history could not be deleted.");
	}

