	private void refreshInbox()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			queueRefresh();
			return;
		}

		conversationList.removeAll();
		if (!repository.isActive())
		{
			loggedInName.setText("Not logged in");
			loggedInWorld.setText("Offline");
			ownAvatarView.setImage(avatarService.getDefaultAvatar());
			inboxSummary.setText("0 conversations");
			conversationList.add(emptyState("Log in to load your DMs."));
		}
		else
		{
			String selfName = repository.getSelfName();
			loggedInName.setText(selfName);
			loggedInWorld.setText(selfWorld > 0 ? "World " + selfWorld : "World unavailable");
			ownAvatarView.setImage(avatarService.getOwnAvatar(selfName));
			avatarService.requestOwnAvatar(selfName, repository.getAccountHash(), this::queueRefresh);
			List<ConversationSummary> allSummaries = repository.getConversationSummaries("");
			int unread = repository.getTotalUnread();
			inboxSummary.setText(allSummaries.size() + (allSummaries.size() == 1 ? " chat" : " chats")
				+ (unread > 0 ? "  •  " + unread + " unread" : ""));
			List<ConversationSummary> summaries = searchField.getText().trim().isEmpty()
				? allSummaries
				: repository.getConversationSummaries(searchField.getText());
			if (summaries.isEmpty())
			{
				conversationList.add(emptyState(searchField.getText().trim().isEmpty()
					? "Private messages with friends will appear here."
					: "No conversations match that search."));
			}
			else
			{
				for (ConversationSummary summary : summaries)
				{
					conversationList.add(buildConversationRow(summary));
					conversationList.add(Box.createVerticalStrut(5));
				}
			}
		}
		conversationList.revalidate();
		conversationList.repaint();
	}

	private void refreshCompose()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			queueRefresh();
			return;
		}

		friendList.removeAll();
		if (!repository.isActive())
		{
			friendSummary.setText("0 friends");
			friendList.add(emptyState("Log in to choose someone from your friends list."));
		}
		else
		{
			List<FriendPresence> snapshot = new ArrayList<>(friends);
			String filter = friendSearchField.getText().trim().toLowerCase(Locale.ROOT);
			List<FriendPresence> matches = new ArrayList<>();
			int onlineCount = 0;
			for (FriendPresence friend : snapshot)
			{
				if (friend.isOnline())
				{
					onlineCount++;
				}
				if (filter.isEmpty() || friend.getDisplayName().toLowerCase(Locale.ROOT).contains(filter))
				{
					matches.add(friend);
				}
			}
			friendSummary.setText(snapshot.size() + (snapshot.size() == 1 ? " friend" : " friends")
				+ (onlineCount > 0 ? "  •  " + onlineCount + " online" : ""));
			if (matches.isEmpty())
			{
				friendList.add(emptyState(filter.isEmpty()
					? "Add friends in RuneScape, then choose one here to start a message."
					: "No friends match that search."));
			}
			else
			{
				for (FriendPresence friend : matches)
				{
					friendList.add(buildFriendRow(friend));
					friendList.add(Box.createVerticalStrut(5));
				}
			}
		}
		friendList.revalidate();
		friendList.repaint();
	}

