	private JPanel buildConversationRow(ConversationSummary summary)
	{
		avatarService.requestAvatar(summary.getPartnerName(), false, repository.getAccountHash(), this::queueRefresh);
		RoundedPanel row = new RoundedPanel(ROW_BACKGROUND);
		row.setLayout(new BorderLayout(9, 0));
		row.setBorder(new EmptyBorder(9, 8, 9, 8));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 77));

		AvatarView avatar = new AvatarView(44, avatarService.getMemoryAvatar(summary.getPartnerName()), ACTIVE_STYLE);
		row.add(avatar, BorderLayout.WEST);

		JPanel text = verticalPanel(ROW_BACKGROUND);
		text.setOpaque(false);
		JPanel top = new JPanel(new BorderLayout(2, 0));
		top.setOpaque(false);
		JLabel name = new JLabel(summary.getPartnerName());
		name.setForeground(PRIMARY_TEXT);
		name.setFont(FontManager.getRunescapeBoldFont().deriveFont(INBOX_NAME_FONT_SIZE));
		name.setToolTipText(summary.getPartnerName());
		name.setMinimumSize(new Dimension(0, name.getPreferredSize().height));
		JPanel nameRow = new JPanel();
		nameRow.setLayout(new BoxLayout(nameRow, BoxLayout.X_AXIS));
		nameRow.setOpaque(false);
		nameRow.add(name);
		Integer friendWorld = getFriendWorld(summary.getPartnerKey());
		if (friendWorld != null)
		{
			nameRow.add(Box.createHorizontalStrut(3));
			PresenceDot online = new PresenceDot(8);
			online.setToolTipText("Online");
			nameRow.add(online);
			nameRow.add(Box.createHorizontalStrut(3));
			JLabel world = new JLabel("W" + friendWorld);
			world.setForeground(ONLINE);
			world.setFont(FontManager.getRunescapeBoldFont().deriveFont(12f));
			world.setToolTipText("World " + friendWorld);
			nameRow.add(world);
		}
		// Keep the name/world area flexible so it yields space before the timestamp.
		// A fixed east column prevents the final AM/PM character from being clipped
		// by RuneLite's narrow sidebar viewport or its vertical scrollbar.
		top.add(nameRow, BorderLayout.CENTER);
		JLabel timestamp = new JLabel(formatListTime(summary.getLastTimestamp()));
		timestamp.setForeground(MUTED_TEXT);
		timestamp.setFont(FontManager.getRunescapeFont().deriveFont(INBOX_TIMESTAMP_FONT_SIZE));
