			? FontManager.getRunescapeBoldFont()
			: FontManager.getRunescapeFont()).deriveFont(INBOX_PREVIEW_FONT_SIZE));
		previewRow.add(preview, BorderLayout.CENTER);
		if (summary.getUnreadCount() > 0)
		{
			JLabel unread = new JLabel(summary.getUnreadCount() > 99 ? "99+" : String.valueOf(summary.getUnreadCount()));
			unread.setOpaque(true);
			unread.setBackground(ACCENT);
			unread.setForeground(ACTIVE_STYLE == RuneDmStyle.MODERN ? Color.WHITE : PANEL_BACKGROUND);
			unread.setHorizontalAlignment(SwingConstants.CENTER);
			unread.setBorder(new EmptyBorder(2, 5, 2, 5));
			unread.setFont(FontManager.getRunescapeBoldFont().deriveFont(11.5f));
			previewRow.add(unread, BorderLayout.EAST);
		}
		text.add(Box.createVerticalStrut(3));
		text.add(previewRow);
		row.add(text, BorderLayout.CENTER);

		MouseAdapter mouse = rowMouseAdapter(row, () -> showConversation(summary));
		attachMouseListenerRecursively(row, mouse);
		setPopupMenuRecursively(
			row,
			friendPopupMenu(summary.getPartnerName(), friendWorld, () -> deleteConversation(summary)));
		return row;
	}

	static String inboxPreviewText(ConversationSummary summary, boolean streamerMode)
	{
