			? "Preview hidden"
			: (summary.isLastOutgoing() ? "You: " : "") + displayMessage(summary.getLastMessage());
	}

	private void refreshConversation()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			queueRefresh();
			return;
		}

		String partnerKey = activePartnerKey;
		if (!conversationVisible || partnerKey == null)
		{
			return;
		}

		List<DmMessage> messages = repository.getMessages(partnerKey);
		if (!messages.isEmpty())
		{
			activePartnerName = messages.get(messages.size() - 1).getPartnerName();
		}
		conversationName.setText(activePartnerName == null ? "Conversation" : activePartnerName);
		Integer friendWorld = getFriendWorld(partnerKey);
		conversationPresence.setVisible(friendWorld != null);
		conversationWorld.setText(friendWorld == null ? " " : "World " + friendWorld);
		conversationWorld.setVisible(friendWorld != null);
		setPopupMenuRecursively(
			conversationIdentity,
			activePartnerName == null
				? null
				: friendPopupMenu(activePartnerName, friendWorld, null));
		if (activePartnerName != null)
		{
			conversationAvatarView.setImage(avatarService.getMemoryAvatar(activePartnerName));
			avatarService.requestAvatar(activePartnerName, false, repository.getAccountHash(), this::queueRefresh);
		}
		messageList.removeAll();

		if (messages.isEmpty())
		{
			messageList.add(emptyState("No saved messages in this conversation."));
		}
		else
		{
			int first = Math.max(0, messages.size() - visibleMessageCount);
			if (first > 0)
			{
				JButton older = button("Load " + Math.min(PAGE_SIZE, first) + " older messages");
				older.setAlignmentX(Component.CENTER_ALIGNMENT);
				older.addActionListener(event ->
				{
					visibleMessageCount += PAGE_SIZE;
					scrollToBottom = false;
					refreshConversation();
				});
				messageList.add(older);
				messageList.add(Box.createVerticalStrut(8));
			}

			LocalDate previousDay = null;
			for (int index = first; index < messages.size(); index++)
			{
				DmMessage message = messages.get(index);
				LocalDate day = Instant.ofEpochMilli(message.getTimestamp()).atZone(ZoneId.systemDefault()).toLocalDate();
				if (!day.equals(previousDay))
				{
					messageList.add(dayDivider(day));
					previousDay = day;
				}
				messageList.add(messageBubble(message));
				messageList.add(Box.createVerticalStrut(5));
			}
		}

		messageList.revalidate();
		messageList.repaint();
		if (scrollToBottom)
		{
			SwingUtilities.invokeLater(() ->
			{
				JScrollBar bar = messageScroll.getVerticalScrollBar();
				bar.setValue(bar.getMaximum());
			});
		}
		scrollToBottom = true;
	}

	private JPanel messageBubble(DmMessage message)
	{
		JPanel row = new JPanel(new FlowLayout(message.isOutgoing() ? FlowLayout.RIGHT : FlowLayout.LEFT, 0, 0));
		row.setOpaque(false);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

		RoundedPanel bubble = new RoundedPanel(message.isOutgoing() ? OUTGOING_BUBBLE : INCOMING_BUBBLE);
		bubble.setLayout(new BorderLayout(0, 5));
		bubble.setBorder(new EmptyBorder(11, 12, 9, 12));
		bubble.setMaximumSize(new Dimension(214, Integer.MAX_VALUE));

		ChatText body = new ChatText(message.getBody(), Font.PLAIN, MESSAGE_FONT_SIZE, PRIMARY_TEXT, 186);
		bubble.add(body, BorderLayout.CENTER);

		JLabel timestamp = new JLabel(formatMessageTimestamp(message.getTimestamp()));
		timestamp.setForeground(TIMESTAMP_TEXT);
		timestamp.setFont(FontManager.getRunescapeFont().deriveFont(MESSAGE_TIMESTAMP_FONT_SIZE));
		timestamp.setHorizontalAlignment(message.isOutgoing() ? SwingConstants.RIGHT : SwingConstants.LEFT);
		bubble.add(timestamp, BorderLayout.SOUTH);
		row.add(bubble);
		JPopupMenu popup = styledPopupMenu();
		JMenuItem delete = menuItem("Delete message");
		delete.addActionListener(event -> deleteMessage(message));
		popup.add(delete);
		setPopupMenuRecursively(row, popup);
		return row;
	}

	private JPanel dayDivider(LocalDate date)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.X_AXIS));
		panel.setOpaque(false);
		panel.setBorder(new EmptyBorder(5, 2, 7, 2));
		panel.add(dividerLine());
		panel.add(Box.createHorizontalStrut(7));
		JLabel label = new JLabel(formatDay(date));
		label.setForeground(MUTED_TEXT);
		label.setFont(FontManager.getRunescapeBoldFont().deriveFont(12.5f));
		panel.add(label);
		panel.add(Box.createHorizontalStrut(7));
		panel.add(dividerLine());
		return panel;
	}

