	private static String formatDay(LocalDate date)
	{
		LocalDate today = LocalDate.now();
		if (date.equals(today))
		{
			return "Today";
		}
		if (date.equals(today.minusDays(1)))
		{
			return "Yesterday";
		}
		return date.isBefore(today.minusYears(1))
			? FULL_DATE_FORMAT.format(date)
			: LIST_DATE_FORMAT.format(date);
	}

	private static String formatListTime(long timestamp)
	{
		return formatListTime(timestamp, Instant.now(), ZoneId.systemDefault());
	}

	static String formatListTime(long timestamp, Instant now, ZoneId zone)
	{
		ZonedDateTime message = Instant.ofEpochMilli(timestamp).atZone(zone);
		ZonedDateTime current = now.atZone(zone);
		if (message.toLocalDate().equals(current.toLocalDate()))
		{
			return TIME_FORMAT.format(message);
		}
		return message.isBefore(current.minusYears(1))
			? FULL_DATE_FORMAT.format(message)
			: LIST_DATE_FORMAT.format(message);
	}

	static String formatMessageTimestamp(long timestamp)
	{
		return formatMessageTimestamp(timestamp, Instant.now(), ZoneId.systemDefault());
	}

	static String formatMessageTimestamp(long timestamp, Instant now, ZoneId zone)
	{
		ZonedDateTime message = Instant.ofEpochMilli(timestamp).atZone(zone);
		return (message.isBefore(now.atZone(zone).minusYears(1))
			? OLD_MESSAGE_TIMESTAMP_FORMAT
			: MESSAGE_TIMESTAMP_FORMAT).format(message);
	}

	private static String ellipsize(String text, int maximum)
	{
		String singleLine = text.replace('\n', ' ').replace('\r', ' ');
		if (singleLine.length() <= maximum)
		{
			return singleLine;
		}
		return singleLine.substring(0, Math.max(0, maximum - 1)) + '\u2026';
	}

	private static String html(String text)
	{
		return text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;")
			.replace("\r", "")
			.replace("\n", "<br>");
	}

