	private void setContextStatus(String message)
	{
		showContextStatus(message, false);
	}

	private void setTemporaryContextStatus(String message)
	{
		showContextStatus(message, true);
		if (message == null || message.isEmpty())
		{
			contextStatusClearTimer.stop();
			clearTemporaryContextStatuses();
		}
		else
		{
			contextStatusClearTimer.restart();
		}
	}

	private void showContextStatus(String message, boolean temporary)
	{
		String displayed = statusText(message);
		if (conversationVisible)
		{
			setStatus(message);
			temporaryReplyStatus = temporary && !" ".equals(displayed) ? displayed : null;
		}
		else if (composeVisible)
		{
			setComposeStatus(message);
			temporaryComposeStatus = temporary && !" ".equals(displayed) ? displayed : null;
		}
		else
		{
			setInboxStatus(message);
			temporaryInboxStatus = temporary && !" ".equals(displayed) ? displayed : null;
		}
	}

	private void clearTemporaryContextStatuses()
	{
		if (temporaryReplyStatus != null && temporaryReplyStatus.equals(replyStatus.getText()))
		{
			replyStatus.setText(" ");
		}
		if (temporaryInboxStatus != null && temporaryInboxStatus.equals(inboxStatus.getText()))
		{
			inboxStatus.setText(" ");
			inboxStatus.setVisible(false);
		}
		if (temporaryComposeStatus != null && temporaryComposeStatus.equals(composeStatus.getText()))
		{
			composeStatus.setText(" ");
			composeStatus.setVisible(false);
		}
		temporaryReplyStatus = null;
		temporaryInboxStatus = null;
		temporaryComposeStatus = null;
		cards.revalidate();
		cards.repaint();
	}

