	void updateSocialState(int currentWorld, List<FriendPresence> friendSnapshot)
	{
		Map<String, FriendPresence> byPlayer = new HashMap<>();
		for (FriendPresence friend : friendSnapshot)
		{
			if (friend != null && friend.isValid())
			{
				byPlayer.put(friend.getPlayerKey(), friend);
			}
		}
		List<FriendPresence> nextFriends = new ArrayList<>(byPlayer.values());
		nextFriends.sort((left, right) ->
		{
			if (left.isOnline() != right.isOnline())
			{
				return left.isOnline() ? -1 : 1;
			}
			return left.getDisplayName().compareToIgnoreCase(right.getDisplayName());
		});

		Map<String, Integer> normalized = new HashMap<>();
		for (FriendPresence friend : nextFriends)
		{
			if (friend.isOnline())
			{
				normalized.put(friend.getPlayerKey(), friend.getWorld());
			}
		}
		Map<String, Integer> nextWorlds = Collections.unmodifiableMap(normalized);
		List<FriendPresence> next = Collections.unmodifiableList(nextFriends);
		if (currentWorld != selfWorld || !nextWorlds.equals(onlineFriendWorlds) || !next.equals(friends))
		{
			selfWorld = currentWorld;
			onlineFriendWorlds = nextWorlds;
			friends = next;
			if (SwingUtilities.isEventDispatchThread())
			{
				refreshAll();
			}
			else
			{
				queueRefresh();
			}
		}
	}

	private Integer getFriendWorld(String playerName)
	{
		return onlineFriendWorlds.get(NameTools.normalize(playerName));
	}

