	private static void paintThemeBackdrop(Graphics graphics, int width, int height)
	{
		Graphics2D graphics2D = (Graphics2D) graphics.create();
		graphics2D.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		BufferedImage wallpaper = ThemeBackgrounds.forStyle(ACTIVE_STYLE);
		if (wallpaper != null)
		{
			graphics2D.setColor(PANEL_BACKGROUND);
			graphics2D.fillRect(0, 0, width, height);
			graphics2D.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			graphics2D.setRenderingHint(RenderingHints.KEY_RENDERING,
				RenderingHints.VALUE_RENDER_QUALITY);
			Rectangle bounds = coverBounds(wallpaper.getWidth(), wallpaper.getHeight(), width, height);
			graphics2D.drawImage(wallpaper, bounds.x, bounds.y, bounds.width, bounds.height, null);

			// Preserve the scene while keeping pale OSRS text readable at sidebar scale.
			Color topShade = new Color(PANEL_BACKGROUND.getRed(), PANEL_BACKGROUND.getGreen(),
				PANEL_BACKGROUND.getBlue(), 145);
			Color bottomShade = new Color(PANEL_BACKGROUND.getRed(), PANEL_BACKGROUND.getGreen(),
				PANEL_BACKGROUND.getBlue(), 205);
			graphics2D.setPaint(new GradientPaint(0, 0, topShade, 0, Math.max(1, height), bottomShade));
			graphics2D.fillRect(0, 0, width, height);
			graphics2D.setColor(new Color(0, 0, 0, 35));
			graphics2D.fillRect(0, 0, width, height);
		}
		else if (ACTIVE_STYLE.wallpaperBackdrop)
		{
			graphics2D.setPaint(new GradientPaint(0, 0, brighten(PANEL_BACKGROUND, 6),
				Math.max(1, width), Math.max(1, height), darken(HEADER_BOTTOM, 5)));
			graphics2D.fillRect(0, 0, width, height);
			graphics2D.setColor(new Color(ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), 18));
			graphics2D.fillOval(width / 3, -Math.max(30, width / 2), Math.max(120, width), Math.max(120, width));
			graphics2D.setColor(new Color(HEADER_TOP.getRed(), HEADER_TOP.getGreen(), HEADER_TOP.getBlue(), 28));
			graphics2D.fillOval(-Math.max(40, width / 2), Math.max(0, height - width), Math.max(150, width), Math.max(150, width));
			graphics2D.setColor(new Color(ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), 9));
			for (int y = 26; y < height; y += 54)
			{
				graphics2D.drawLine(0, y, width, Math.max(0, y - 22));
			}
		}
		else
		{
			graphics2D.setColor(PANEL_BACKGROUND);
			graphics2D.fillRect(0, 0, width, height);
		}
		graphics2D.dispose();
	}

	static Rectangle coverBounds(int sourceWidth, int sourceHeight, int targetWidth, int targetHeight)
	{
		if (sourceWidth <= 0 || sourceHeight <= 0 || targetWidth <= 0 || targetHeight <= 0)
		{
			return new Rectangle();
		}

		double scale = Math.max(targetWidth / (double) sourceWidth, targetHeight / (double) sourceHeight);
		int width = Math.max(targetWidth, (int) Math.ceil(sourceWidth * scale));
		int height = Math.max(targetHeight, (int) Math.ceil(sourceHeight * scale));
		return new Rectangle((targetWidth - width) / 2, (targetHeight - height) / 2, width, height);
	}

	private static Color brighten(Color color, int amount)
	{
		return new Color(
			Math.min(255, color.getRed() + amount),
			Math.min(255, color.getGreen() + amount),
			Math.min(255, color.getBlue() + amount),
			color.getAlpha());
	}

	private static Color darken(Color color, int amount)
	{
		return new Color(
			Math.max(0, color.getRed() - amount),
			Math.max(0, color.getGreen() - amount),
			Math.max(0, color.getBlue() - amount),
			color.getAlpha());
	}

	private static Color withAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(),
			Math.max(0, Math.min(255, alpha)));
	}

	private static Color blend(Color first, Color second, int secondPercent)
	{
		int percent = Math.max(0, Math.min(100, secondPercent));
		int firstPercent = 100 - percent;
		return new Color(
			(first.getRed() * firstPercent + second.getRed() * percent) / 100,
			(first.getGreen() * firstPercent + second.getGreen() * percent) / 100,
			(first.getBlue() * firstPercent + second.getBlue() * percent) / 100,
			Math.max(first.getAlpha(), second.getAlpha()));
	}

