	private static void setPopupMenuRecursively(Component component, JPopupMenu popup)
	{
		if (component instanceof JComponent)
		{
			JComponent swingComponent = (JComponent) component;
			swingComponent.setComponentPopupMenu(popup);
			for (Component child : swingComponent.getComponents())
			{
				setPopupMenuRecursively(child, popup);
			}
		}
	}

	private static void attachMouseListenerRecursively(Component component, MouseAdapter listener)
	{
		component.addMouseListener(listener);
		component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		if (component instanceof JComponent)
		{
			for (Component child : ((JComponent) component).getComponents())
			{
				attachMouseListenerRecursively(child, listener);
			}
		}
	}

	private static final class RoundedPanel extends JPanel
	{
		private static final long serialVersionUID = 1L;

		private Color fill;

		private RoundedPanel(Color fill)
		{
			this.fill = fill;
			setOpaque(false);
		}

		private void setFill(Color fill)
		{
			this.fill = fill;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D graphics2D = (Graphics2D) graphics.create();
			graphics2D.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int radius = ACTIVE_STYLE.cornerRadius;
			Color paintedFill = fill;
			if (ACTIVE_STYLE.wallpaperResource != null)
			{
				boolean messageBubble = fill == OUTGOING_BUBBLE || fill == INCOMING_BUBBLE;
				paintedFill = withAlpha(fill, messageBubble ? 242 : 230);
			}
			if (ACTIVE_STYLE.beveled)
			{
				graphics2D.setPaint(new GradientPaint(0, 0, brighten(paintedFill, 8), 0, getHeight(), darken(paintedFill, 9)));
				graphics2D.fillRoundRect(0, 0, getWidth(), getHeight(), radius, radius);
				graphics2D.setColor(darken(BORDER, 38));
				graphics2D.drawRoundRect(0, 0, Math.max(0, getWidth() - 1), Math.max(0, getHeight() - 1), radius, radius);
				graphics2D.setColor(new Color(BORDER.getRed(), BORDER.getGreen(), BORDER.getBlue(), 150));
				graphics2D.drawLine(3, 1, Math.max(3, getWidth() - 4), 1);
				graphics2D.setColor(new Color(255, 224, 168, 28));
				graphics2D.drawLine(4, 2, Math.max(4, getWidth() - 5), 2);
			}
			else
			{
				graphics2D.setColor(paintedFill);
				graphics2D.fillRoundRect(0, 0, getWidth(), getHeight(), radius, radius);
				graphics2D.setColor(new Color(255, 255, 255, 20));
				graphics2D.drawRoundRect(0, 0, Math.max(0, getWidth() - 1), Math.max(0, getHeight() - 1), radius, radius);
			}
			graphics2D.dispose();
			super.paintComponent(graphics);
		}
	}

