	private static final class GradientPanel extends JPanel
	{
		private static final long serialVersionUID = 1L;

		private final Color top;
		private final Color bottom;

		private GradientPanel(Color top, Color bottom)
		{
			this.top = top;
			this.bottom = bottom;
			setOpaque(false);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D graphics2D = (Graphics2D) graphics.create();
			graphics2D.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			Color paintedTop = ACTIVE_STYLE.wallpaperResource == null ? top : withAlpha(top, 224);
			Color paintedBottom = ACTIVE_STYLE.wallpaperResource == null ? bottom : withAlpha(bottom, 224);
			graphics2D.setPaint(new GradientPaint(0, 0, paintedTop, 0, getHeight(), paintedBottom));
			int radius = ACTIVE_STYLE == RuneDmStyle.MODERN ? 18 : ACTIVE_STYLE.cornerRadius + 2;
			graphics2D.fillRoundRect(0, 0, getWidth(), getHeight(), radius, radius);
			graphics2D.setColor(ACTIVE_STYLE.beveled ? BORDER : new Color(255, 255, 255, 28));
			graphics2D.drawRoundRect(0, 0, Math.max(0, getWidth() - 1), Math.max(0, getHeight() - 1), radius, radius);
			if (ACTIVE_STYLE.beveled)
			{
				graphics2D.setColor(new Color(255, 225, 170, 36));
				graphics2D.drawLine(4, 2, Math.max(4, getWidth() - 5), 2);
			}
			graphics2D.dispose();
			super.paintComponent(graphics);
		}
	}

	private static final class RoundedButton extends JButton
	{
		private static final long serialVersionUID = 1L;

		private final Color fill;
		private final Color hover;

		private RoundedButton(String text, Color fill, Color hover)
		{
			super(text);
			this.fill = fill;
			this.hover = hover;
			setOpaque(false);
			setContentAreaFilled(false);
			setBorderPainted(false);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D graphics2D = (Graphics2D) graphics.create();
			graphics2D.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			Color color = getModel().isPressed() ? fill.darker() : getModel().isRollover() ? hover : fill;
			Color painted = isEnabled() ? color : new Color(color.getRed(), color.getGreen(), color.getBlue(), 100);
			int radius = ACTIVE_STYLE == RuneDmStyle.MODERN ? 10 : 6;
			if (ACTIVE_STYLE.beveled)
			{
				graphics2D.setPaint(new GradientPaint(0, 0, brighten(painted, 13), 0, getHeight(), darken(painted, 14)));
			}
			else
			{
				graphics2D.setColor(painted);
			}
			graphics2D.fillRoundRect(0, 0, getWidth(), getHeight(), radius, radius);
			if (ACTIVE_STYLE.beveled)
			{
				graphics2D.setColor(darken(BORDER, 30));
				graphics2D.drawRoundRect(0, 0, Math.max(0, getWidth() - 1), Math.max(0, getHeight() - 1), radius, radius);
				graphics2D.setColor(new Color(255, 235, 190, 45));
				graphics2D.drawLine(3, 1, Math.max(3, getWidth() - 4), 1);
			}
			graphics2D.dispose();
			super.paintComponent(graphics);
		}
	}

	private static final class PlaceholderTextField extends JTextField
	{
		private static final long serialVersionUID = 1L;

		private final String placeholder;

		private PlaceholderTextField(String placeholder)
		{
			this.placeholder = placeholder;
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			super.paintComponent(graphics);
			if (!getText().isEmpty())
			{
				return;
			}
			Graphics2D graphics2D = (Graphics2D) graphics.create();
			graphics2D.setColor(MUTED_TEXT);
			graphics2D.setFont(getFont());
			Insets insets = getInsets();
			int y = (getHeight() - graphics2D.getFontMetrics().getHeight()) / 2
				+ graphics2D.getFontMetrics().getAscent();
			graphics2D.drawString(placeholder, insets.left, y);
			graphics2D.dispose();
		}
	}

}

