package com.runedm;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

final class DmEmoji
{
	static final class Choice
	{
		private final String display;
		private final String token;
		private final String name;

		private Choice(String display, String token, String name)
		{
			this.display = display;
			this.token = token;
			this.name = name;
		}

		String getDisplay()
		{
			return display;
		}

		String getToken()
		{
			return token;
		}

		String getName()
		{
			return name;
		}
	}

	private static final List<Choice> CHOICES = Collections.unmodifiableList(Arrays.asList(
		new Choice("🙂", ":)", "Smile"),
		new Choice("😂", "=')", "Laugh"),
		new Choice("😊", "^_^", "Blush"),
		new Choice("😁", ":D", "Grin"),
		new Choice("😉", ";)", "Wink"),
		new Choice("😛", ":P", "Tongue"),
		new Choice("🤔", ":-?", "Thinking"),
		new Choice("😕", ":/", "Confused"),
		new Choice("🙁", ":(", "Frown"),
		new Choice("😢", ":'(", "Cry"),
		new Choice("😭", ":_(", "Sob"),
		new Choice("😎", "8-)", "Cool"),
		new Choice("😇", "O:)", "Angel"),
		new Choice("😈", ">:)", "Imp"),
		new Choice("👍", "(Y)", "Thumbs up"),
		new Choice("👎", "(N)", "Thumbs down"),
		new Choice("❤️", "<3", "Heart"),
		new Choice("🔥", "(/\\)", "Fire"),
		new Choice("👀", "O.O", "Eyes"),
		new Choice("👋", "(^_^)/", "Wave"),
		new Choice("😍", "(*.*)", "Heart eyes"),
		new Choice("💩", "~@~", "Poo"),
		new Choice("🎉", "@@@", "Party"),
		new Choice("🤝", "(=)", "Handshake")
	));

	private static final List<Choice> RENDER_ORDER;

	static
	{
		List<Choice> choices = new ArrayList<>(CHOICES);
		choices.sort(Comparator.comparingInt((Choice choice) -> choice.token.length()).reversed());
		RENDER_ORDER = Collections.unmodifiableList(choices);
	}

	private DmEmoji()
	{
	}

	static List<Choice> choices()
	{
		return CHOICES;
	}

	static String render(String message)
	{
		if (message == null || message.isEmpty())
		{
			return message == null ? "" : message;
		}

		String rendered = message;
		for (Choice choice : RENDER_ORDER)
		{
			rendered = rendered.replace(choice.token, choice.display);
		}
		return rendered;
	}

	static String encode(String message)
	{
		if (message == null || message.isEmpty())
		{
			return message == null ? "" : message;
		}

		String encoded = message;
		for (Choice choice : CHOICES)
		{
			encoded = encoded.replace(choice.display, choice.token);
		}
		return encoded;
	}
}

