import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Text;
import okhttp3.OkHttpClient;

@PluginDescriptor(
	name = "Direct Messages",
	description = "Keeps private messages in a local inbox with search, unread counts, and optional portraits",
	tags = {"chat", "message", "private", "dm", "friends", "history", "timestamps", "runeprofile", "online", "world", "hop", "theme", "osrs"}
)
public class RuneDmPlugin extends Plugin implements RuneDmActions
{
	private static final long MINIMUM_VALID_UNIX_SECONDS = 946684800L;
	private static final int SOCIAL_REFRESH_TICKS = 3;
	private static final int WORLD_HOP_MAX_WAIT_TICKS = 60;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Gson gson;

	@Inject
	private OkHttpClient httpClient;

	@Inject
	private RuneDmConfig config;

	private MessageStore messageStore;
	private DmRepository repository;
	private AvatarService avatarService;
	private RuneDmPanel panel;
	private NavigationButton navigationButton;
	private long activeAccountHash;
	private long captureStartedMillis;
	private int socialRefreshTicks;
	private Integer pendingHopWorldId;
	private BiConsumer<Boolean, String> pendingHopResult;
	private int worldHopWaitTicks;

	@Provides
	RuneDmConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RuneDmConfig.class);
	}

	@Override
	protected void startUp()
	{
		Path dataDirectory = RuneLite.RUNELITE_DIR.toPath().resolve("runedm");
		messageStore = new MessageStore(gson, dataDirectory);
		repository = new DmRepository(messageStore);
		avatarService = new AvatarService(httpClient, config, messageStore);
		installThemedPanel();
		socialRefreshTicks = 0;
		clientThread.invoke(this::activateAccountIfReady);
	}

	@Override
	protected void shutDown()
	{
		cancelPendingWorldHop("Direct Messages stopped before the world hop completed.");
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
		if (panel != null)
		{
			panel.dispose();
			panel = null;
		}
		if (repository != null)
		{
			repository.deactivate();
			repository = null;
		}
		if (avatarService != null)
		{
			avatarService.close();
			avatarService = null;
		}
		if (messageStore != null)
		{
			messageStore.close();
			messageStore = null;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			activateAccountIfReady();
			refreshSocialState();
		}
		else
		{
			if (pendingHopWorldId != null)
			{
				cancelPendingWorldHop("World hop cancelled because you logged out.");
			}
			clearSocialState();
			if (event.getGameState() == GameState.LOGIN_SCREEN && repository != null)
			{
				repository.deactivate();
				activeAccountHash = 0L;
				captureStartedMillis = 0L;
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		processPendingWorldHop();
		if (repository != null && !repository.isActive())
		{
			activateAccountIfReady();
		}
		if (++socialRefreshTicks >= SOCIAL_REFRESH_TICKS)
		{
			socialRefreshTicks = 0;
			refreshSocialState();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (repository == null)
		{
			return;
		}

		ChatMessageType type = event.getType();
		boolean outgoing;
		if (type == ChatMessageType.PRIVATECHATOUT)
		{
			outgoing = true;
		}
		else if (type == ChatMessageType.PRIVATECHAT || type == ChatMessageType.MODPRIVATECHAT)
		{
			outgoing = false;
		}
		else
		{
			return;
		}

		if (!repository.isActive())
		{
			activateAccountIfReady();
		}
		if (!repository.isActive())
		{
			return;
		}

		String partnerName = NameTools.displayName(event.getName());
		if (partnerName.isEmpty() || !client.isFriended(partnerName, false))
		{
			return;
		}

		String body = event.getMessage() == null ? "" : Text.unescapeJagex(event.getMessage()).trim();
		if (body.isEmpty())
		{
			return;
		}

		long eventSeconds = event.getTimestamp();
		if (eventSeconds < MINIMUM_VALID_UNIX_SECONDS && event.getMessageNode() != null)
		{
			eventSeconds = event.getMessageNode().getTimestamp();
		}
		long timestamp = eventSeconds >= MINIMUM_VALID_UNIX_SECONDS
			? eventSeconds * 1000L
			: System.currentTimeMillis();
		// RuneLite's Chat History plugin can replay older chatbox rows on login.
		// Direct Messages already has its own persistent copy, so do not import that replay.
		if (captureStartedMillis > 0L && timestamp < captureStartedMillis)
		{
			return;
		}

		long sourceId = event.getMessageNode() == null
			? System.nanoTime()
			: Integer.toUnsignedLong(event.getMessageNode().getId());
		DmMessage message = DmMessage.create(partnerName, body, timestamp, outgoing, sourceId);
		if (repository.addMessage(message)
			&& !outgoing
			&& panel != null
			&& panel.isViewing(message.getPartnerKey()))
		{
			repository.markRead(message.getPartnerKey());
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!RuneDmConfig.GROUP.equals(event.getGroup()) || avatarService == null)
		{
			return;
		}
		String key = event.getKey();
		if ("interfaceStyle".equals(key))
		{
			installThemedPanel();
			clientThread.invoke(this::refreshSocialState);
			return;
		}
		boolean avatarSetting = "runeProfileAvatars".equals(key);
		if (avatarSetting)
		{
			avatarService.resetRemoteAttempts();
		}
		if (panel != null)
		{
			panel.refreshPanel();
		}
		if (avatarSetting)
		{
			clientThread.invoke(this::refreshSocialState);
		}
	}

	private void installThemedPanel()
	{
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
		if (panel != null)
		{
			panel.dispose();
		}
		panel = new RuneDmPanel(repository, avatarService, this, config);
		navigationButton = NavigationButton.builder()
			.tooltip("Direct Messages")
			.icon(UiImages.navigationIcon(config.interfaceStyle()))
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
	}

	private void activateAccountIfReady()
	{
		if (repository == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || localPlayer.getName() == null)
		{
			return;
		}

		String selfName = NameTools.displayName(localPlayer.getName());
		long accountHash = client.getAccountHash();
		if (accountHash == 0L)
		{
			accountHash = Long.parseUnsignedLong(NameTools.avatarHash(selfName).substring(0, 16), 16);
		}
		if (!repository.isActive() || activeAccountHash != accountHash)
		{
			activeAccountHash = accountHash;
			// Timestamps are second-resolution; retain a small boundary allowance.
			captureStartedMillis = System.currentTimeMillis() - 10_000L;
		}
		repository.activate(accountHash, selfName);
	}

	private void refreshSocialState()
	{
		if (repository == null || panel == null || avatarService == null
			|| !repository.isActive() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		List<FriendPresence> friends = new ArrayList<>();
		FriendContainer friendContainer = client.getFriendContainer();
		if (friendContainer != null)
		{
			for (Friend friend : friendContainer.getMembers())
			{
				if (friend != null && friend.getName() != null)
				{
					FriendPresence presence = new FriendPresence(friend.getName(), friend.getWorld());
					if (presence.isValid())
					{
						friends.add(presence);
					}
				}
			}
		}
		panel.updateSocialState(client.getWorld(), friends);

	}

	private void clearSocialState()
	{
		socialRefreshTicks = 0;
		if (panel != null)
		{
			panel.updateSocialState(0, Collections.emptyList());
		}
	}

	@Override
	public void openNativeReply(String target, BiConsumer<Boolean, String> result)
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN || !client.isFriended(target, true))
			{
				result.accept(false, "That friend is offline.");
				return;
			}
			client.runScript(ScriptID.OPEN_PRIVATE_MESSAGE_INTERFACE, target);
			result.accept(true, "RuneScape reply box opened.");
		});
	}

	@Override
	public void hopToWorld(int worldId, BiConsumer<Boolean, String> result)
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				result.accept(false, "Log in before hopping worlds.");
				return;
			}
			if (worldId <= 0)
			{
				result.accept(false, "That friend is offline.");
				return;
			}
			if (client.getWorld() == worldId)
			{
				result.accept(false, "You are already on World " + worldId + '.');
				return;
			}
			if (pendingHopWorldId != null)
			{
				result.accept(false, "Another world hop is already in progress.");
				return;
			}

			pendingHopWorldId = worldId;
			pendingHopResult = result;
			worldHopWaitTicks = 0;
			processPendingWorldHop();
		});
	}

	private World findWorld(int worldId)
	{
		return findWorld(client.getWorldList(), worldId);
	}

	static World findWorld(World[] worlds, int worldId)
	{
		if (worlds == null)
		{
			return null;
		}
		for (World world : worlds)
		{
			if (world != null && world.getId() == worldId)
			{
				return world;
			}
		}
		return null;
	}

	private void processPendingWorldHop()
	{
		if (pendingHopWorldId == null)
		{
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			cancelPendingWorldHop("World hop cancelled because you are not logged in.");
			return;
		}

		if (client.getWidget(InterfaceID.Worldswitcher.BUTTONS) == null)
		{
			client.openWorldHopper();
		}
		else
		{
			World target = findWorld(pendingHopWorldId);
			if (target != null)
			{
				int worldId = pendingHopWorldId;
				client.hopToWorld(target);
				completePendingWorldHop(true, "Hopping to World " + worldId + "...");
				return;
			}
		}

		if (++worldHopWaitTicks >= WORLD_HOP_MAX_WAIT_TICKS)
		{
			cancelPendingWorldHop("Could not load World " + pendingHopWorldId + '.');
		}
	}

	private void cancelPendingWorldHop(String message)
	{
		completePendingWorldHop(false, message);
	}

	private void completePendingWorldHop(boolean success, String message)
	{
		BiConsumer<Boolean, String> result = pendingHopResult;
		pendingHopWorldId = null;
		pendingHopResult = null;
		worldHopWaitTicks = 0;
		if (result != null)
		{
			result.accept(success, message);
		}
	}
}

