package com.runedm;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

final class AvatarView extends JComponent
{
	private static final long serialVersionUID = 1L;

	private BufferedImage image;
	private final RuneDmStyle style;

	AvatarView(int size, BufferedImage image)
	{
		this(size, image, RuneDmStyle.MODERN);
	}

	AvatarView(int size, BufferedImage image, RuneDmStyle style)
	{
		this.image = image;
		this.style = style == null ? RuneDmStyle.OSRS : style;
		Dimension dimension = new Dimension(size, size);
		setPreferredSize(dimension);
		setMinimumSize(dimension);
		setMaximumSize(dimension);
		setOpaque(false);
	}

	void setImage(BufferedImage image)
	{
		this.image = image;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D graphics2D = (Graphics2D) graphics.create();
		graphics2D.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		Shape circle = new Ellipse2D.Double(0, 0, getWidth() - 1, getHeight() - 1);
		graphics2D.setClip(circle);
		graphics2D.drawImage(image, 0, 0, getWidth(), getHeight(), null);
		graphics2D.setClip(null);
		graphics2D.setColor(style == RuneDmStyle.MODERN
			? new Color(255, 255, 255, 45)
			: new Color(style.accent.getRed(), style.accent.getGreen(), style.accent.getBlue(), 190));
		graphics2D.draw(circle);
		if (style.beveled && getWidth() > 5 && getHeight() > 5)
		{
			graphics2D.setColor(new Color(12, 10, 8, 180));
			graphics2D.draw(new Ellipse2D.Double(2, 2, getWidth() - 5, getHeight() - 5));
		}
		graphics2D.dispose();
	}
}

