package com.runedm;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;
import net.runelite.client.util.Text;

final class NameTools
{
	private NameTools()
	{
	}

	static String displayName(String value)
	{
		if (value == null)
		{
			return "";
		}

		return Text.toJagexName(Text.removeTags(value)).replace('\u00A0', ' ').trim();
	}

	static String normalize(String value)
	{
		return displayName(value).replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	static String avatarHash(String playerName)
	{
		return sha256Hex("runedm-avatar-v1|" + normalize(playerName));
	}

	static String messageId(String partnerKey, boolean outgoing, String body, long timestamp)
	{
		return messageId(partnerKey, outgoing, body, timestamp, 0L);
	}

	static String messageId(String partnerKey, boolean outgoing, String body, long timestamp, long sourceId)
	{
		return sha256Hex("runedm-message-v1|" + partnerKey + '|' + outgoing + '|'
			+ timestamp + '|' + sourceId + '|' + body);
	}

	private static String sha256Hex(String input)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] bytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
			StringBuilder result = new StringBuilder(bytes.length * 2);
			for (byte value : bytes)
			{
				result.append(String.format(Locale.ROOT, "%02x", value & 0xff));
			}
			return result.toString();
		}
		catch (NoSuchAlgorithmException ex)
		{
			throw new IllegalStateException("SHA-256 is unavailable", ex);
		}
	}
}

