	}

	static BufferedImage emojiIcon(DmEmoji.Choice choice, int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		graphics.scale(size / 24d, size / 24d);
		switch (choice.getName())
		{
			case "Thumbs up":
				drawThumb(graphics, false);
				break;
			case "Thumbs down":
				drawThumb(graphics, true);
				break;
			case "Heart":
				drawHeart(graphics, 3, 4, 18, new Color(238, 72, 91));
				break;
			case "Fire":
				drawFire(graphics);
				break;
			case "Eyes":
				drawEyes(graphics);
				break;
			case "Wave":
				drawWave(graphics);
				break;
			case "Poo":
				drawPoo(graphics);
				break;
			case "Party":
				drawParty(graphics);
				break;
			case "Handshake":
				drawHandshake(graphics);
				break;
			default:
				drawFace(graphics, choice.getName());
				break;
		}
		graphics.dispose();
		return image;
	}

	private static void drawFace(Graphics2D graphics, String expression)
	{
		Color faceColor = "Imp".equals(expression) ? new Color(139, 91, 214) : new Color(255, 202, 61);
		graphics.setColor(faceColor);
		graphics.fillOval(2, 2, 20, 20);
		graphics.setStroke(new BasicStroke(1.1f));
		graphics.setColor(faceColor.darker());
		graphics.draw(new Ellipse2D.Double(2.5, 2.5, 19, 19));
		graphics.setStroke(new BasicStroke(1.7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		if ("Angel".equals(expression))
		{
			graphics.setColor(new Color(128, 213, 255));
			graphics.drawOval(6, 0, 12, 4);
		}
		else if ("Imp".equals(expression))
		{
			graphics.setColor(new Color(112, 65, 184));
			Path2D horns = new Path2D.Double();
			horns.moveTo(4, 6);
			horns.lineTo(3, 1);
			horns.lineTo(8, 4);
			horns.moveTo(20, 6);
			horns.lineTo(21, 1);
			horns.lineTo(16, 4);
			graphics.draw(horns);
		}

		graphics.setColor(new Color(79, 58, 42));
		if ("Laugh".equals(expression) || "Blush".equals(expression))
		{
			graphics.drawArc(6, 7, 4, 3, 15, 150);
			graphics.drawArc(14, 7, 4, 3, 15, 150);
		}
		else if ("Wink".equals(expression))
		{
			graphics.drawLine(6, 9, 9, 8);
			graphics.fillOval(15, 7, 2, 3);
		}
		else if ("Cool".equals(expression))
		{
			graphics.setStroke(new BasicStroke(1.2f));
			graphics.fillRoundRect(5, 7, 6, 5, 2, 2);
			graphics.fillRoundRect(13, 7, 6, 5, 2, 2);
			graphics.drawLine(11, 9, 13, 9);
		}
		else if ("Heart eyes".equals(expression))
		{
			drawHeart(graphics, 5, 7, 5, new Color(220, 46, 67));
			drawHeart(graphics, 14, 7, 5, new Color(220, 46, 67));
		}
		else
		{
			graphics.fillOval(6, 7, 3, 3);
			graphics.fillOval(15, 7, 3, 3);
		}

		if ("Laugh".equals(expression))
		{
			graphics.setColor(new Color(92, 62, 48));
			graphics.fillRoundRect(7, 12, 10, 7, 5, 5);
			graphics.setColor(Color.WHITE);
			graphics.fillRoundRect(8, 12, 8, 2, 2, 2);
			graphics.setColor(new Color(72, 174, 232));
			Path2D tear = new Path2D.Double();
			tear.moveTo(3, 11);
			tear.curveTo(0, 15, 2, 18, 4, 17);
			tear.curveTo(6, 16, 6, 14, 3, 11);
			graphics.fill(tear);
		}
		else if ("Grin".equals(expression))
		{
			graphics.setColor(Color.WHITE);
			graphics.fillRoundRect(6, 13, 12, 5, 2, 2);
			graphics.setColor(new Color(98, 69, 48));
			graphics.drawRoundRect(6, 13, 12, 5, 2, 2);
			graphics.drawLine(10, 13, 10, 18);
			graphics.drawLine(14, 13, 14, 18);
		}
		else if ("Tongue".equals(expression))
		{
			graphics.setColor(new Color(94, 58, 48));
			graphics.fillRoundRect(7, 13, 10, 5, 5, 5);
			graphics.setColor(new Color(238, 105, 136));
			graphics.fillOval(10, 16, 5, 5);
		}
		else if ("Thinking".equals(expression))
		{
			graphics.drawLine(7, 15, 13, 14);
			graphics.setColor(new Color(246, 179, 65));
			graphics.fillOval(15, 15, 6, 6);
			graphics.setColor(new Color(79, 58, 42));
			graphics.drawLine(17, 14, 19, 11);
		}
		else if ("Confused".equals(expression))
		{
			graphics.drawLine(7, 17, 16, 14);
		}
		else if ("Frown".equals(expression))
		{
			graphics.drawArc(7, 15, 10, 6, 25, 130);
		}
		else if ("Cry".equals(expression) || "Sob".equals(expression))
		{
			graphics.drawArc(8, 15, 8, 5, 25, 130);
			graphics.setColor(new Color(65, 166, 231));
			drawTear(graphics, 6, 10);
			if ("Sob".equals(expression))
			{
				drawTear(graphics, 17, 10);
			}
		}
		else if ("Imp".equals(expression))
		{
			graphics.drawArc(7, 12, 10, 6, 205, 130);
		}
		else
		{
			graphics.drawArc(7, 11, 10, 7, 205, 130);
		}

		if ("Blush".equals(expression))
		{
			graphics.setColor(new Color(244, 118, 132, 170));
			graphics.fillOval(4, 11, 4, 3);
			graphics.fillOval(16, 11, 4, 3);
		}
	}

	private static void drawTear(Graphics2D graphics, double x, double y)
	{
		Path2D tear = new Path2D.Double();
		tear.moveTo(x, y);
		tear.curveTo(x - 2, y + 4, x - 1, y + 7, x + 1, y + 7);
		tear.curveTo(x + 3, y + 6, x + 3, y + 4, x, y);
		graphics.fill(tear);
	}

	private static void drawHeart(Graphics2D graphics, double x, double y, double size, Color color)
	{
		Path2D heart = new Path2D.Double();
		heart.moveTo(x + size / 2, y + size);
		heart.curveTo(x - size * .15, y + size * .55, x, y, x + size * .3, y);
		heart.curveTo(x + size * .48, y, x + size * .5, y + size * .2, x + size / 2, y + size * .25);
		heart.curveTo(x + size * .5, y + size * .2, x + size * .7, y, x + size * .88, y);
		heart.curveTo(x + size * 1.2, y, x + size * 1.15, y + size * .55, x + size / 2, y + size);
		graphics.setColor(color);
		graphics.fill(heart);
	}

	private static void drawThumb(Graphics2D graphics, boolean down)
	{
		Graphics2D oriented = (Graphics2D) graphics.create();
		if (down)
		{
			oriented.rotate(Math.PI, 12, 12);
		}
		Path2D thumb = new Path2D.Double();
		thumb.moveTo(5, 10);
		thumb.lineTo(10, 10);
		thumb.lineTo(13, 4);
		thumb.curveTo(14, 2, 17, 3, 16, 6);
		thumb.lineTo(15, 9);
		thumb.lineTo(20, 9);
		thumb.curveTo(22, 9, 22, 11, 21, 13);
		thumb.lineTo(19, 19);
		thumb.lineTo(10, 19);
		thumb.lineTo(10, 20);
		thumb.lineTo(5, 20);
		thumb.closePath();
		oriented.setColor(new Color(255, 195, 95));
		oriented.fill(thumb);
		oriented.setColor(new Color(181, 123, 50));
		oriented.setStroke(new BasicStroke(1.1f));
		oriented.draw(thumb);
		oriented.drawLine(10, 10, 10, 19);
		oriented.dispose();
	}

	private static void drawFire(Graphics2D graphics)
	{
		Path2D flame = new Path2D.Double();
		flame.moveTo(12, 22);
		flame.curveTo(3, 20, 4, 12, 10, 7);
		flame.curveTo(10, 11, 13, 9, 15, 2);
		flame.curveTo(22, 9, 23, 18, 12, 22);
		graphics.setColor(new Color(244, 91, 48));
		graphics.fill(flame);
		Path2D center = new Path2D.Double();
		center.moveTo(12, 20);
		center.curveTo(8, 18, 9, 14, 13, 10);
		center.curveTo(17, 15, 17, 19, 12, 20);
		graphics.setColor(new Color(255, 202, 55));
		graphics.fill(center);
	}

	private static void drawEyes(Graphics2D graphics)
	{
		graphics.setColor(Color.WHITE);
		graphics.fillOval(2, 5, 9, 14);
		graphics.fillOval(13, 5, 9, 14);
		graphics.setColor(new Color(62, 76, 91));
		graphics.setStroke(new BasicStroke(1.1f));
		graphics.drawOval(2, 5, 9, 14);
		graphics.drawOval(13, 5, 9, 14);
		graphics.setColor(new Color(42, 47, 54));
		graphics.fillOval(7, 10, 3, 5);
		graphics.fillOval(14, 10, 3, 5);
