		hand.curveTo(10, 1, 12, 1, 13, 3);
		hand.lineTo(13, 4);
		hand.curveTo(13, 2, 15, 2, 16, 4);
		hand.lineTo(16, 6);
		hand.curveTo(17, 4, 19, 5, 19, 7);
