		hands.lineTo(15, 9);
		hands.lineTo(18, 12);
		hands.lineTo(14, 17);
		hands.lineTo(11, 15);
		hands.lineTo(8, 16);
		hands.lineTo(5, 13);
		hands.closePath();
		graphics.setColor(new Color(255, 195, 95));
