import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/**
 * Renders conversation text with RuneLite's in-game RuneScape font while using
 * an emoji-capable fallback only for glyphs the game font cannot display.
 */
final class ChatText extends JComponent
{
	private static final long serialVersionUID = 1L;
	private static final FontRenderContext FONT_CONTEXT = new FontRenderContext(null, true, true);

	private final List<TextLayout> layouts = new ArrayList<>();
	private final int preferredWidth;
	private final int preferredHeight;

	ChatText(String message, int style, float size, Color color, int maxWidth)
	{
		String text = DmEmoji.render(message == null ? "" : message);
		Font chatFont = runescapeChatFont(style, size);
		Font fallback = new Font("Segoe UI Emoji", style, Math.round(size));
		AttributedString attributed = new AttributedString(text.isEmpty() ? " " : text);
		attributed.addAttribute(TextAttribute.FONT, chatFont);
		attributed.addAttribute(TextAttribute.FOREGROUND, color);

		for (int index = 0; index < text.length();)
		{
			int codePoint = text.codePointAt(index);
			int end = index + Character.charCount(codePoint);
			if (!chatFont.canDisplay(codePoint))
			{
				attributed.addAttribute(TextAttribute.FONT, fallback, index, end);
			}
			index = end;
		}

		AttributedCharacterIterator iterator = attributed.getIterator();
		LineBreakMeasurer measurer = new LineBreakMeasurer(iterator, FONT_CONTEXT);
		float width = 0f;
		float height = 0f;
		int safeWidth = Math.max(1, maxWidth);
		while (measurer.getPosition() < iterator.getEndIndex())
		{
			TextLayout layout = measurer.nextLayout(safeWidth);
			layouts.add(layout);
			width = Math.max(width, layout.getAdvance());
			height += layout.getAscent() + layout.getDescent() + layout.getLeading();
		}
		preferredWidth = Math.max(1, Math.min(safeWidth, (int) Math.ceil(width)));
		preferredHeight = Math.max(1, (int) Math.ceil(height));
		setOpaque(false);
		setForeground(color);
		setFont(chatFont);
	}

	static Font runescapeChatFont(int style, float size)
	{
		Font base = style == Font.BOLD
			? FontManager.getRunescapeBoldFont()
			: FontManager.getRunescapeFont();
		return base.deriveFont(style, size);
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(preferredWidth, preferredHeight);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D graphics2D = (Graphics2D) graphics.create();
		graphics2D.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
			RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		float y = 0f;
		for (TextLayout layout : layouts)
		{
			y += layout.getAscent();
			layout.draw(graphics2D, 0f, y);
			y += layout.getDescent() + layout.getLeading();
		}
		graphics2D.dispose();
	}
}

