package com.runedm;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class MessageStore
{
	private static final Logger LOG = LoggerFactory.getLogger(MessageStore.class);
	private static final String MESSAGE_FILE = "messages.jsonl";
	private static final String READ_STATE_FILE = "read-state.json";

	private final Gson gson;
	private final Path rootDirectory;
	private final ExecutorService ioExecutor;

	MessageStore(Gson gson, Path rootDirectory)
	{
		this.gson = gson;
		this.rootDirectory = rootDirectory;
		ThreadFactory threadFactory = runnable ->
		{
			Thread thread = new Thread(runnable, "runedm-storage");
			return thread;
		};
		this.ioExecutor = Executors.newSingleThreadExecutor(threadFactory);
	}

	CompletableFuture<LoadedHistory> load(long accountHash)
	{
		return CompletableFuture.supplyAsync(() -> loadNow(accountHash), ioExecutor);
	}

	CompletableFuture<Void> append(long accountHash, DmMessage message)
	{
		return CompletableFuture.runAsync(() ->
		{
			try
			{
				Path accountDirectory = accountDirectory(accountHash);
				Files.createDirectories(accountDirectory);
				Files.write(
					accountDirectory.resolve(MESSAGE_FILE),
					Collections.singletonList(gson.toJson(message)),
					StandardCharsets.UTF_8,
					StandardOpenOption.CREATE,
					StandardOpenOption.APPEND);
			}
			catch (IOException ex)
			{
				LOG.warn("Unable to save a Direct Messages entry", ex);
			}
		}, ioExecutor);
	}

	CompletableFuture<Void> replaceMessages(long accountHash, List<DmMessage> messages)
	{
		List<DmMessage> snapshot = new ArrayList<>(messages);
		return CompletableFuture.runAsync(() ->
		{
			try
			{
				Path accountDirectory = accountDirectory(accountHash);
				Files.createDirectories(accountDirectory);
				Path target = accountDirectory.resolve(MESSAGE_FILE);
				Path temporary = accountDirectory.resolve(MESSAGE_FILE + ".tmp");
				List<String> lines = new ArrayList<>(snapshot.size());
				for (DmMessage message : snapshot)
				{
					lines.add(gson.toJson(message));
				}
				Files.write(
					temporary,
					lines,
					StandardCharsets.UTF_8,
					StandardOpenOption.CREATE,
					StandardOpenOption.TRUNCATE_EXISTING);
				moveAtomically(temporary, target);
			}
			catch (IOException ex)
			{
				LOG.warn("Unable to rewrite Direct Messages history", ex);
			}
		}, ioExecutor);
	}

	CompletableFuture<Void> saveReadState(long accountHash, Map<String, Long> readThrough)
	{
		Map<String, Long> snapshot = new HashMap<>(readThrough);
		return CompletableFuture.runAsync(() ->
		{
			try
			{
				Path accountDirectory = accountDirectory(accountHash);
				Files.createDirectories(accountDirectory);
				Path target = accountDirectory.resolve(READ_STATE_FILE);
				Path temporary = accountDirectory.resolve(READ_STATE_FILE + ".tmp");
				Files.write(
					temporary,
					gson.toJson(snapshot).getBytes(StandardCharsets.UTF_8),
					StandardOpenOption.CREATE,
					StandardOpenOption.TRUNCATE_EXISTING);

				moveAtomically(temporary, target);
			}
			catch (IOException ex)
			{
				LOG.warn("Unable to save Direct Messages read state", ex);
			}
		}, ioExecutor);
	}

	private static void moveAtomically(Path temporary, Path target) throws IOException
	{
		try
		{
			Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (AtomicMoveNotSupportedException ex)
		{
			Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	Path accountDirectory(long accountHash)
	{
		return rootDirectory.resolve("accounts").resolve(Long.toUnsignedString(accountHash, 16));
	}

	Path runeProfileAvatarCacheDirectory()
	{
		return rootDirectory.resolve("runeprofile-avatar-cache");
	}

	private LoadedHistory loadNow(long accountHash)
	{
		List<DmMessage> messages = new ArrayList<>();
		Map<String, Long> readThrough = new HashMap<>();
		Path accountDirectory = accountDirectory(accountHash);
		Path messagePath = accountDirectory.resolve(MESSAGE_FILE);
		Path readStatePath = accountDirectory.resolve(READ_STATE_FILE);

		try
		{
			Files.createDirectories(accountDirectory);
		}
		catch (IOException ex)
		{
			LOG.warn("Unable to create the Direct Messages data directory", ex);
			return new LoadedHistory(messages, readThrough);
		}

		if (Files.isRegularFile(messagePath))
		{
			try (BufferedReader reader = Files.newBufferedReader(messagePath, StandardCharsets.UTF_8))
			{
				String line;
				while ((line = reader.readLine()) != null)
				{
					if (line.trim().isEmpty())
					{
						continue;
					}

					try
					{
						DmMessage message = gson.fromJson(line, DmMessage.class);
						if (message != null && message.isValid())
						{
							messages.add(message);
						}
					}
					catch (JsonParseException ex)
					{
						LOG.debug("Skipping a damaged Direct Messages history line", ex);
					}
				}
			}
			catch (IOException ex)
			{
				LOG.warn("Unable to load Direct Messages history", ex);
			}
		}

		if (Files.isRegularFile(readStatePath))
		{
			try (BufferedReader reader = Files.newBufferedReader(readStatePath, StandardCharsets.UTF_8))
			{
				JsonObject loaded = gson.fromJson(reader, JsonObject.class);
				if (loaded != null)
				{
					for (Map.Entry<String, JsonElement> entry : loaded.entrySet())
					{
						JsonElement value = entry.getValue();
						if (value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber())
						{
							readThrough.put(entry.getKey(), value.getAsLong());
						}
					}
				}
			}
			catch (IOException | JsonParseException ex)
			{
				LOG.warn("Unable to load Direct Messages read state", ex);
			}
		}

		return new LoadedHistory(messages, readThrough);
	}

	void close()
	{
		// Let already-queued appends and read-state snapshots finish. The executor
		// remains off the client thread, so shutting the plugin down never blocks it.
		ioExecutor.shutdown();
	}
}

