package com.runedm;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Small, dependency-free software renderer for the public character model returned by RuneProfile.
 * RuneProfile exports either binary glTF (current) or binary PLY (legacy) models with vertex colours.
 */
final class RuneProfileModelRenderer
{
	private static final int GLB_MAGIC = 0x46546c67;
	private static final int JSON_CHUNK = 0x4e4f534a;
	private static final int BIN_CHUNK = 0x004e4942;
	private static final float GAME_UNITS_PER_GLTF_UNIT = 128f;
	private static final int MAX_VERTICES = 200_000;
	private static final int MAX_TRIANGLES = 300_000;
	private static final int MAX_GRID_CELLS = 2_000_000;
	private static final int MAX_DEFAULT_MODEL_BYTES = 128 * 1024;
	private static final int SUPERSAMPLE = 2;
	private static final float PORTRAIT_CROP = 0.40f;
	private static final float HEADROOM = 0.08f;
	private static final float PADDING = 0.03f;
	private static final float FRONT_YAW = (float) Math.PI;
	private static final float BODY_CELL = 4f;
	private static final float MIN_LIMB_WIDTH = 12f;
	private static final float HEAD_TOP = 202f;
	private static final float HEAD_BAND_LOW = 150f;
	private static final float HEAD_BAND_HIGH = 215f;
	private static final float MIN_BODY_HEIGHT = 150f;
	private static final Pattern VERTEX_COUNT = Pattern.compile("(?m)^element vertex (\\d+)\\s*$");
	private static final Pattern FACE_COUNT = Pattern.compile("(?m)^element face (\\d+)\\s*$");

	private RuneProfileModelRenderer()
	{
	}

	static BufferedImage renderHeadshot(byte[] modelBytes, int size) throws IOException
	{
		if (modelBytes == null || modelBytes.length < 16 || size < 16 || size > 512)
		{
			throw new IOException("Invalid RuneProfile model");
		}

		Mesh mesh = isGlb(modelBytes) ? parseGlb(modelBytes) : parsePly(modelBytes);
		if (mesh.positions.length == 0 || mesh.indices.length == 0)
		{
			throw new IOException("RuneProfile model has no renderable faces");
		}
		return render(mesh, size);
	}

	private static boolean isGlb(byte[] bytes)
	{
		return bytes.length >= 4
			&& (bytes[0] & 0xff) == 0x67
			&& (bytes[1] & 0xff) == 0x6c
			&& (bytes[2] & 0xff) == 0x54
			&& (bytes[3] & 0xff) == 0x46;
	}

	private static Mesh parseGlb(byte[] data) throws IOException
	{
		ByteBuffer buffer = ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);
		if (data.length < 20 || buffer.getInt(0) != GLB_MAGIC || buffer.getInt(4) != 2)
		{
			throw new IOException("Invalid binary glTF header");
		}
		int declaredLength = buffer.getInt(8);
		if (declaredLength < 20 || declaredLength > data.length)
		{
			throw new IOException("Invalid binary glTF length");
		}

		JsonObject document = null;
		int binaryOffset = -1;
		int binaryLength = 0;
		int offset = 12;
		while (offset + 8 <= declaredLength)
		{
			int chunkLength = buffer.getInt(offset);
			int chunkType = buffer.getInt(offset + 4);
			int chunkStart = offset + 8;
			if (chunkLength < 0 || chunkStart > declaredLength - chunkLength)
			{
				throw new IOException("Invalid binary glTF chunk");
			}
			if (chunkType == JSON_CHUNK)
			{
				String json = new String(data, chunkStart, chunkLength, StandardCharsets.UTF_8).trim();
				try
				{
					document = new JsonParser().parse(json).getAsJsonObject();
				}
				catch (RuntimeException ex)
				{
					throw new IOException("Invalid binary glTF JSON", ex);
				}
			}
			else if (chunkType == BIN_CHUNK)
			{
				binaryOffset = chunkStart;
				binaryLength = chunkLength;
			}
			offset = chunkStart + chunkLength;
		}

		if (document == null)
		{
			throw new IOException("Binary glTF has no JSON chunk");
		}

		GlbReader reader = new GlbReader(data, document, binaryOffset, binaryLength);
		FloatBuilder positions = new FloatBuilder();
		ByteBuilder colors = new ByteBuilder();
		IntBuilder indices = new IntBuilder();
		JsonArray nodes = array(document, "nodes");
		boolean[] visiting = new boolean[nodes == null ? 0 : nodes.size()];
		List<Integer> roots = sceneRoots(document, nodes);
		for (int root : roots)
		{
			visitNode(reader, root, identity(), positions, colors, indices, visiting, 0);
		}

		return mesh(positions, colors, indices);
	}

	private static List<Integer> sceneRoots(JsonObject document, JsonArray nodes)
	{
		JsonArray scenes = array(document, "scenes");
		int sceneIndex = integer(document, "scene", 0);
		if (scenes != null && sceneIndex >= 0 && sceneIndex < scenes.size())
		{
			JsonArray roots = array(scenes.get(sceneIndex).getAsJsonObject(), "nodes");
			if (roots != null)
			{
				List<Integer> result = new ArrayList<>();
				for (JsonElement root : roots)
				{
					result.add(root.getAsInt());
				}
				return result;
			}
		}

		if (nodes == null)
		{
			return Collections.emptyList();
		}
		boolean[] child = new boolean[nodes.size()];
		for (JsonElement element : nodes)
		{
			JsonArray children = array(element.getAsJsonObject(), "children");
			if (children == null)
			{
				continue;
			}
			for (JsonElement value : children)
			{
				int index = value.getAsInt();
				if (index >= 0 && index < child.length)
				{
					child[index] = true;
				}
			}
		}
		List<Integer> roots = new ArrayList<>();
		for (int index = 0; index < child.length; index++)
		{
			if (!child[index])
			{
				roots.add(index);
			}
		}
		return roots;
	}

	private static void visitNode(
		GlbReader reader,
		int nodeIndex,
		float[] parent,
		FloatBuilder positions,
		ByteBuilder colors,
		IntBuilder indices,
		boolean[] visiting,
		int depth) throws IOException
	{
		JsonArray nodes = array(reader.document, "nodes");
		if (nodes == null || nodeIndex < 0 || nodeIndex >= nodes.size() || depth > 64)
		{
			throw new IOException("Invalid binary glTF node graph");
		}
		if (visiting[nodeIndex])
		{
			throw new IOException("Cyclic binary glTF node graph");
		}
		visiting[nodeIndex] = true;
		JsonObject node = nodes.get(nodeIndex).getAsJsonObject();
		float[] world = multiply(parent, nodeMatrix(node));

		int meshIndex = integer(node, "mesh", -1);
		if (meshIndex >= 0)
		{
			JsonArray meshes = array(reader.document, "meshes");
			if (meshes == null || meshIndex >= meshes.size())
			{
				throw new IOException("Invalid binary glTF mesh");
			}
			JsonArray primitives = array(meshes.get(meshIndex).getAsJsonObject(), "primitives");
			if (primitives != null)
			{
				for (JsonElement primitive : primitives)
				{
					appendPrimitive(reader, primitive.getAsJsonObject(), world, positions, colors, indices);
				}
			}
		}

		JsonArray children = array(node, "children");
		if (children != null)
		{
			for (JsonElement child : children)
			{
				visitNode(reader, child.getAsInt(), world, positions, colors, indices, visiting, depth + 1);
			}
		}
		visiting[nodeIndex] = false;
	}

	private static void appendPrimitive(
		GlbReader reader,
		JsonObject primitive,
		float[] world,
		FloatBuilder positions,
		ByteBuilder colors,
		IntBuilder indices) throws IOException
	{
		if (integer(primitive, "mode", 4) != 4)
		{
			return;
		}
		JsonObject attributes = object(primitive, "attributes");
		if (attributes == null || !attributes.has("POSITION"))
		{
			return;
		}
		Accessor position = reader.accessor(attributes.get("POSITION").getAsInt());
		if (position.components < 3 || position.count() > MAX_VERTICES - positions.size() / 3)
		{
			throw new IOException("RuneProfile model has too many vertices");
		}
		Accessor color = attributes.has("COLOR_0")
			? reader.accessor(attributes.get("COLOR_0").getAsInt())
			: null;
		if (color != null && color.count() != position.count())
		{
			throw new IOException("Invalid binary glTF colours");
		}

		float[] factor = materialColor(reader.document, integer(primitive, "material", -1));
		float[] alpha = new float[position.count()];
		int vertexBase = positions.size() / 3;
		for (int index = 0; index < position.count(); index++)
		{
			float x = position.values[index * position.components];
			float y = position.values[index * position.components + 1];
			float z = position.values[index * position.components + 2];
			float wx = world[0] * x + world[4] * y + world[8] * z + world[12];
			float wy = world[1] * x + world[5] * y + world[9] * z + world[13];
			float wz = world[2] * x + world[6] * y + world[10] * z + world[14];
			positions.add(wx * GAME_UNITS_PER_GLTF_UNIT);
			positions.add(-wz * GAME_UNITS_PER_GLTF_UNIT);
			positions.add(wy * GAME_UNITS_PER_GLTF_UNIT);

			float red = factor[0];
			float green = factor[1];
			float blue = factor[2];
			float opacity = factor[3];
			if (color != null)
			{
				red = color.values[index * color.components];
				green = color.components > 1 ? color.values[index * color.components + 1] : red;
				blue = color.components > 2 ? color.values[index * color.components + 2] : red;
				if (color.components > 3)
				{
					opacity = color.values[index * color.components + 3];
				}
			}
			colors.add(channel(red));
			colors.add(channel(green));
			colors.add(channel(blue));
			alpha[index] = opacity;
		}

		int[] faceIndices;
		if (primitive.has("indices"))
		{
			Accessor accessor = reader.accessor(primitive.get("indices").getAsInt());
			faceIndices = new int[accessor.values.length];
			for (int index = 0; index < faceIndices.length; index++)
			{
				faceIndices[index] = Math.round(accessor.values[index]);
			}
		}
		else
		{
			faceIndices = new int[position.count()];
			for (int index = 0; index < faceIndices.length; index++)
			{
				faceIndices[index] = index;
			}
		}

		for (int offset = 0; offset + 2 < faceIndices.length; offset += 3)
		{
			int a = faceIndices[offset];
			int b = faceIndices[offset + 1];
			int c = faceIndices[offset + 2];
			if (a < 0 || b < 0 || c < 0 || a >= alpha.length || b >= alpha.length || c >= alpha.length)
			{
				throw new IOException("Invalid binary glTF face");
			}
			if ((alpha[a] + alpha[b] + alpha[c]) / 3f < 0.5f)
			{
				continue;
			}
			if (indices.size() / 3 >= MAX_TRIANGLES)
			{
				throw new IOException("RuneProfile model has too many faces");
			}
			indices.add(vertexBase + a);
			indices.add(vertexBase + b);
			indices.add(vertexBase + c);
		}
	}

	private static Mesh parsePly(byte[] data) throws IOException
	{
		int marker = indexOf(data, "end_header".getBytes(StandardCharsets.ISO_8859_1));
		if (marker < 0 || marker > 8 * 1024)
		{
			throw new IOException("Invalid RuneProfile PLY header");
		}
		int dataOffset = marker + "end_header".length();
		while (dataOffset < data.length && data[dataOffset] != '\n')
		{
			dataOffset++;
		}
		dataOffset++;
		String header = new String(data, 0, Math.min(dataOffset, data.length), StandardCharsets.ISO_8859_1);
		if (!header.contains("format binary_little_endian"))
		{
			throw new IOException("RuneProfile PLY is not little-endian binary");
		}
		int vertexCount = count(header, VERTEX_COUNT);
		int faceCount = count(header, FACE_COUNT);
		if (vertexCount < 1 || vertexCount > MAX_VERTICES || faceCount < 1 || faceCount > MAX_TRIANGLES)
		{
			throw new IOException("Invalid RuneProfile PLY counts");
		}

		ByteBuffer buffer = ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);
		if (dataOffset > data.length - vertexCount * 9L)
		{
			throw new IOException("Truncated RuneProfile PLY vertices");
		}
		float[] positions = new float[vertexCount * 3];
		byte[] colors = new byte[vertexCount * 3];
		for (int vertex = 0; vertex < vertexCount; vertex++)
		{
			positions[vertex * 3] = buffer.getShort(dataOffset);
			positions[vertex * 3 + 1] = buffer.getShort(dataOffset + 2);
			positions[vertex * 3 + 2] = buffer.getShort(dataOffset + 4);
			colors[vertex * 3] = data[dataOffset + 6];
			colors[vertex * 3 + 1] = data[dataOffset + 7];
			colors[vertex * 3 + 2] = data[dataOffset + 8];
			dataOffset += 9;
		}

		IntBuilder indices = new IntBuilder();
		for (int face = 0; face < faceCount; face++)
		{
			if (dataOffset >= data.length)
			{
				throw new IOException("Truncated RuneProfile PLY faces");
			}
			int points = data[dataOffset++] & 0xff;
			if (points < 3 || dataOffset > data.length - points * 2L)
			{
				throw new IOException("Invalid RuneProfile PLY face");
			}
			int first = buffer.getShort(dataOffset) & 0xffff;
			for (int triangle = 1; triangle + 1 < points; triangle++)
			{
				int second = buffer.getShort(dataOffset + triangle * 2) & 0xffff;
				int third = buffer.getShort(dataOffset + (triangle + 1) * 2) & 0xffff;
				if (first >= vertexCount || second >= vertexCount || third >= vertexCount)
				{
					throw new IOException("Invalid RuneProfile PLY face index");
				}
				indices.add(first);
				indices.add(second);
				indices.add(third);
			}
			dataOffset += points * 2;
		}
		return new Mesh(positions, colors, indices.toArray());
	}

	private static BufferedImage render(Mesh mesh, int size) throws IOException
	{
		int width = size * SUPERSAMPLE;
		int height = size * SUPERSAMPLE;
		int vertexCount = mesh.positions.length / 3;
		float[] transformed = new float[mesh.positions.length];
		float minimumModelZ = Float.POSITIVE_INFINITY;
		for (int vertex = 0; vertex < vertexCount; vertex++)
		{
			minimumModelZ = Math.min(minimumModelZ, mesh.positions[vertex * 3 + 2]);
		}
		float cosine = (float) Math.cos(FRONT_YAW);
		float sine = (float) Math.sin(FRONT_YAW);
		for (int vertex = 0; vertex < vertexCount; vertex++)
		{
			float modelX = mesh.positions[vertex * 3];
			float modelY = mesh.positions[vertex * 3 + 1];
			float modelZ = mesh.positions[vertex * 3 + 2];
			transformed[vertex * 3] = modelX * cosine - modelY * sine;
			transformed[vertex * 3 + 1] = modelZ - minimumModelZ;
			transformed[vertex * 3 + 2] = modelX * sine + modelY * cosine;
		}

		BodyFrame body = estimateBody(transformed, mesh.indices);
		float minimumY = Float.POSITIVE_INFINITY;
		for (int vertex = 0; vertex < vertexCount; vertex++)
		{
			minimumY = Math.min(minimumY, transformed[vertex * 3 + 1]);
		}
		float cropMinimumY = body.top - (body.top - minimumY) * PORTRAIT_CROP;
		float spanY = Math.max(1f, body.top - cropMinimumY);
		float scale = height * (1f - HEADROOM - PADDING) / spanY;
		float anchorX = width * 0.5f;
		float yBase = height * HEADROOM + body.top * scale;

		int[] pixels = new int[width * height];
		fillBackground(pixels, width, height);
		float[] depth = new float[pixels.length];
		Arrays.fill(depth, Float.NEGATIVE_INFINITY);
		for (int face = 0; face < mesh.indices.length; face += 3)
		{
			int a = mesh.indices[face];
			int b = mesh.indices[face + 1];
			int c = mesh.indices[face + 2];
			float ax = anchorX + (transformed[a * 3] - body.headCenterX) * scale;
			float ay = yBase - transformed[a * 3 + 1] * scale;
			float az = transformed[a * 3 + 2];
			float bx = anchorX + (transformed[b * 3] - body.headCenterX) * scale;
			float by = yBase - transformed[b * 3 + 1] * scale;
			float bz = transformed[b * 3 + 2];
			float cx = anchorX + (transformed[c * 3] - body.headCenterX) * scale;
			float cy = yBase - transformed[c * 3 + 1] * scale;
			float cz = transformed[c * 3 + 2];
			rasterizeTriangle(pixels, depth, width, height, mesh.colors, a, b, c,
				ax, ay, az, bx, by, bz, cx, cy, cz);
		}

		BufferedImage supersampled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		supersampled.setRGB(0, 0, width, height, pixels, 0, width);
		return scale(supersampled, size);
	}

	private static void rasterizeTriangle(
		int[] pixels,
		float[] depth,
		int width,
		int height,
		byte[] colors,
		int a,
		int b,
		int c,
		float ax,
		float ay,
		float az,
		float bx,
		float by,
		float bz,
		float cx,
		float cy,
		float cz)
	{
		float denominator = (by - cy) * (ax - cx) + (cx - bx) * (ay - cy);
		if (Math.abs(denominator) < 0.000001f)
		{
			return;
		}
		int minimumX = Math.max(0, (int) Math.floor(Math.min(ax, Math.min(bx, cx))));
		int maximumX = Math.min(width - 1, (int) Math.ceil(Math.max(ax, Math.max(bx, cx))));
		int minimumY = Math.max(0, (int) Math.floor(Math.min(ay, Math.min(by, cy))));
		int maximumY = Math.min(height - 1, (int) Math.ceil(Math.max(ay, Math.max(by, cy))));
		for (int y = minimumY; y <= maximumY; y++)
		{
			for (int x = minimumX; x <= maximumX; x++)
			{
				float sampleX = x + 0.5f;
				float sampleY = y + 0.5f;
				float first = ((by - cy) * (sampleX - cx) + (cx - bx) * (sampleY - cy)) / denominator;
				if (first < 0f)
				{
					continue;
				}
				float second = ((cy - ay) * (sampleX - cx) + (ax - cx) * (sampleY - cy)) / denominator;
				if (second < 0f)
				{
					continue;
				}
				float third = 1f - first - second;
				if (third < 0f)
				{
					continue;
				}
				float z = first * az + second * bz + third * cz;
				int pixel = y * width + x;
				if (z <= depth[pixel])
				{
					continue;
				}
				depth[pixel] = z;
				int red = Math.round(first * unsigned(colors[a * 3])
					+ second * unsigned(colors[b * 3]) + third * unsigned(colors[c * 3]));
				int green = Math.round(first * unsigned(colors[a * 3 + 1])
					+ second * unsigned(colors[b * 3 + 1]) + third * unsigned(colors[c * 3 + 1]));
				int blue = Math.round(first * unsigned(colors[a * 3 + 2])
					+ second * unsigned(colors[b * 3 + 2]) + third * unsigned(colors[c * 3 + 2]));
				pixels[pixel] = 0xff000000 | (red << 16) | (green << 8) | blue;
			}
		}
	}

	private static BodyFrame estimateBody(float[] points, int[] indices)
	{
		float minimumX = Float.POSITIVE_INFINITY;
		float maximumX = Float.NEGATIVE_INFINITY;
		float minimumY = Float.POSITIVE_INFINITY;
		float maximumY = Float.NEGATIVE_INFINITY;
		for (int vertex = 0; vertex < points.length / 3; vertex++)
		{
			float x = points[vertex * 3];
			float y = points[vertex * 3 + 1];
			minimumX = Math.min(minimumX, x);
			maximumX = Math.max(maximumX, x);
			minimumY = Math.min(minimumY, y);
			maximumY = Math.max(maximumY, y);
		}
		BodyFrame bounds = new BodyFrame(maximumY, (minimumX + maximumX) * 0.5f);
		if (maximumY - minimumY < MIN_BODY_HEIGHT || maximumX <= minimumX)
		{
			return bounds;
		}

		int columns = (int) Math.ceil((maximumX - minimumX) / BODY_CELL) + 1;
		int rows = (int) Math.ceil((maximumY - minimumY) / BODY_CELL) + 1;
		if (columns < 1 || rows < 1 || (long) columns * rows > MAX_GRID_CELLS)
		{
			return bounds;
		}
		byte[] silhouette = new byte[columns * rows];
		for (int face = 0; face < indices.length; face += 3)
		{
			int a = indices[face];
			int b = indices[face + 1];
			int c = indices[face + 2];
			float ax = (points[a * 3] - minimumX) / BODY_CELL;
			float ay = (points[a * 3 + 1] - minimumY) / BODY_CELL;
			float bx = (points[b * 3] - minimumX) / BODY_CELL;
			float by = (points[b * 3 + 1] - minimumY) / BODY_CELL;
			float cx = (points[c * 3] - minimumX) / BODY_CELL;
			float cy = (points[c * 3 + 1] - minimumY) / BODY_CELL;
			float denominator = (by - cy) * (ax - cx) + (cx - bx) * (ay - cy);
			if (Math.abs(denominator) < 0.000001f)
			{
				continue;
			}
			int x0 = Math.max(0, (int) Math.floor(Math.min(ax, Math.min(bx, cx))));
			int x1 = Math.min(columns - 1, (int) Math.ceil(Math.max(ax, Math.max(bx, cx))));
			int y0 = Math.max(0, (int) Math.floor(Math.min(ay, Math.min(by, cy))));
			int y1 = Math.min(rows - 1, (int) Math.ceil(Math.max(ay, Math.max(by, cy))));
			for (int row = y0; row <= y1; row++)
			{
				for (int column = x0; column <= x1; column++)
				{
					float x = column + 0.5f;
					float y = row + 0.5f;
					float first = ((by - cy) * (x - cx) + (cx - bx) * (y - cy)) / denominator;
					float second = ((cy - ay) * (x - cx) + (ax - cx) * (y - cy)) / denominator;
					if (first >= 0f && second >= 0f && 1f - first - second >= 0f)
					{
						silhouette[row * columns + column] = 1;
					}
				}
			}
		}

		int minimumRun = Math.max(1, Math.round(MIN_LIMB_WIDTH / BODY_CELL));
		byte[] thick = new byte[silhouette.length];
		for (int row = 0; row < rows; row++)
		{
			int run = 0;
			for (int column = 0; column <= columns; column++)
			{
				boolean filled = column < columns && silhouette[row * columns + column] == 1;
				if (filled)
				{
					run++;
					continue;
				}
				if (run >= minimumRun)
				{
					for (int keep = column - run; keep < column; keep++)
					{
						thick[row * columns + keep] = 1;
					}
				}
				run = 0;
			}
		}

		int[] labels = new int[thick.length];
		Arrays.fill(labels, -1);
		int[] stack = new int[thick.length];
		int bestLabel = -1;
		int bestArea = 0;
		int nextLabel = 0;
		for (int start = 0; start < thick.length; start++)
		{
			if (thick[start] != 1 || labels[start] != -1)
			{
				continue;
			}
			int label = nextLabel++;
			int stackSize = 0;
			int area = 0;
			stack[stackSize++] = start;
			labels[start] = label;
			while (stackSize > 0)
			{
				int cell = stack[--stackSize];
				area++;
				int row = cell / columns;
				int column = cell % columns;
				stackSize = push(thick, labels, stack, stackSize, label, rows, columns, row - 1, column);
				stackSize = push(thick, labels, stack, stackSize, label, rows, columns, row + 1, column);
				stackSize = push(thick, labels, stack, stackSize, label, rows, columns, row, column - 1);
				stackSize = push(thick, labels, stack, stackSize, label, rows, columns, row, column + 1);
			}
			if (area > bestArea)
			{
				bestArea = area;
				bestLabel = label;
			}
		}
		if (bestLabel < 0)
		{
			return bounds;
		}

		int bodyTopRow = -1;
		for (int row = rows - 1; row >= 0; row--)
		{
			if (bodyRun(labels, bestLabel, row, columns, minimumX).width > 0f)
			{
				bodyTopRow = row;
				break;
			}
		}
		if (bodyTopRow * BODY_CELL < MIN_BODY_HEIGHT)
		{
			return bounds;
		}

		int headStart = rowAt(HEAD_BAND_LOW, rows);
		int headEnd = rowAt(HEAD_BAND_HIGH, rows);
		List<Float> headCenters = new ArrayList<>();
		for (int row = headStart; row <= headEnd; row++)
		{
			Run run = bodyRun(labels, bestLabel, row, columns, minimumX);
			if (run.width > 0f)
			{
				headCenters.add(run.middle);
			}
		}
		Collections.sort(headCenters);
		float headCenter = headCenters.isEmpty()
			? bounds.headCenterX
			: headCenters.get(headCenters.size() / 2);
		return new BodyFrame(minimumY + HEAD_TOP, headCenter);
	}

	private static int push(
		byte[] thick,
		int[] labels,
		int[] stack,
		int stackSize,
		int label,
		int rows,
		int columns,
		int row,
		int column)
	{
		if (row < 0 || row >= rows || column < 0 || column >= columns)
		{
			return stackSize;
		}
		int cell = row * columns + column;
		if (thick[cell] == 1 && labels[cell] == -1)
		{
			labels[cell] = label;
			stack[stackSize++] = cell;
		}
		return stackSize;
	}

	private static Run bodyRun(int[] labels, int label, int row, int columns, float minimumX)
	{
		int run = 0;
		int best = 0;
		int start = -1;
		int bestStart = -1;
		for (int column = 0; column < columns; column++)
		{
			if (labels[row * columns + column] == label)
			{
				if (run == 0)
				{
					start = column;
				}
				run++;
				if (run > best)
				{
					best = run;
					bestStart = start;
				}
			}
			else
			{
				run = 0;
			}
		}
		return bestStart < 0
			? new Run(0f, 0f)
			: new Run(best * BODY_CELL, minimumX + (bestStart + best / 2f) * BODY_CELL);
	}

	private static int rowAt(float height, int rows)
	{
		return Math.min(rows - 1, Math.max(0, Math.round(height / BODY_CELL)));
	}

	private static void fillBackground(int[] pixels, int width, int height)
	{
		float centerX = (width - 1) * 0.5f;
		float centerY = height * 0.34f;
		float radius = Math.max(width, height) * 0.72f;
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				float dx = x - centerX;
				float dy = y - centerY;
				float distance = Math.min(1f, (float) Math.sqrt(dx * dx + dy * dy) / radius);
				int value = Math.round(35f - distance * 16f);
				pixels[y * width + x] = 0xff000000 | (value << 16) | ((value + 2) << 8) | value + 5;
			}
		}
	}

	private static BufferedImage scale(BufferedImage source, int size)
	{
		BufferedImage result = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = result.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		graphics.drawImage(source, 0, 0, size, size, null);
		graphics.dispose();
		return result;
	}

	private static float[] materialColor(JsonObject document, int materialIndex)
	{
		float[] fallback = {1f, 1f, 1f, 1f};
		JsonArray materials = array(document, "materials");
		if (materials == null || materialIndex < 0 || materialIndex >= materials.size())
		{
			return fallback;
		}
		JsonObject pbr = object(materials.get(materialIndex).getAsJsonObject(), "pbrMetallicRoughness");
		JsonArray factor = pbr == null ? null : array(pbr, "baseColorFactor");
		if (factor == null || factor.size() < 3)
		{
			return fallback;
		}
		return new float[]{
			factor.get(0).getAsFloat(),
			factor.get(1).getAsFloat(),
			factor.get(2).getAsFloat(),
			factor.size() > 3 ? factor.get(3).getAsFloat() : 1f
		};
	}

	private static float[] nodeMatrix(JsonObject node)
	{
		JsonArray matrix = array(node, "matrix");
		if (matrix != null && matrix.size() == 16)
		{
			float[] values = new float[16];
			for (int index = 0; index < values.length; index++)
			{
				values[index] = matrix.get(index).getAsFloat();
			}
			return values;
		}

		float[] translation = vector(node, "translation", new float[]{0f, 0f, 0f});
		float[] rotation = vector(node, "rotation", new float[]{0f, 0f, 0f, 1f});
		float[] scale = vector(node, "scale", new float[]{1f, 1f, 1f});
		float qx = rotation[0];
		float qy = rotation[1];
		float qz = rotation[2];
		float qw = rotation[3];
		float x2 = qx + qx;
		float y2 = qy + qy;
		float z2 = qz + qz;
		float xx = qx * x2;
		float xy = qx * y2;
		float xz = qx * z2;
		float yy = qy * y2;
		float yz = qy * z2;
		float zz = qz * z2;
		float wx = qw * x2;
		float wy = qw * y2;
		float wz = qw * z2;
		return new float[]{
			(1f - (yy + zz)) * scale[0], (xy + wz) * scale[0], (xz - wy) * scale[0], 0f,
			(xy - wz) * scale[1], (1f - (xx + zz)) * scale[1], (yz + wx) * scale[1], 0f,
			(xz + wy) * scale[2], (yz - wx) * scale[2], (1f - (xx + yy)) * scale[2], 0f,
			translation[0], translation[1], translation[2], 1f
		};
	}

	private static float[] multiply(float[] left, float[] right)
	{
		float[] result = new float[16];
		for (int column = 0; column < 4; column++)
		{
			for (int row = 0; row < 4; row++)
			{
				float sum = 0f;
				for (int inner = 0; inner < 4; inner++)
				{
					sum += left[inner * 4 + row] * right[column * 4 + inner];
				}
				result[column * 4 + row] = sum;
			}
		}
		return result;
	}

	private static float[] identity()
	{
		return new float[]{1f, 0f, 0f, 0f, 0f, 1f, 0f, 0f, 0f, 0f, 1f, 0f, 0f, 0f, 0f, 1f};
	}

	private static float[] vector(JsonObject object, String name, float[] fallback)
	{
		JsonArray array = array(object, name);
		if (array == null || array.size() != fallback.length)
		{
			return fallback;
		}
		float[] result = new float[fallback.length];
		for (int index = 0; index < result.length; index++)
		{
			result[index] = array.get(index).getAsFloat();
		}
		return result;
	}

	private static Mesh mesh(FloatBuilder positions, ByteBuilder colors, IntBuilder indices) throws IOException
	{
		if (positions.size() / 3 > MAX_VERTICES || indices.size() / 3 > MAX_TRIANGLES)
		{
			throw new IOException("RuneProfile model is too complex");
		}
		return new Mesh(positions.toArray(), colors.toArray(), indices.toArray());
	}

	private static int count(String header, Pattern pattern) throws IOException
	{
		Matcher matcher = pattern.matcher(header);
		if (!matcher.find())
		{
			throw new IOException("RuneProfile PLY count is missing");
		}
		try
		{
			return Integer.parseInt(matcher.group(1));
		}
		catch (NumberFormatException ex)
		{
			throw new IOException("Invalid RuneProfile PLY count", ex);
		}
	}

	private static int indexOf(byte[] data, byte[] needle)
	{
		outer:
		for (int offset = 0; offset <= data.length - needle.length; offset++)
		{
			for (int index = 0; index < needle.length; index++)
			{
				if (data[offset + index] != needle[index])
				{
					continue outer;
				}
			}
			return offset;
		}
		return -1;
	}

	private static byte[] readLimited(InputStream input, int maximum) throws IOException
	{
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		byte[] buffer = new byte[8192];
		int total = 0;
		int read;
		while ((read = input.read(buffer)) != -1)
		{
			total += read;
			if (total > maximum)
			{
				return null;
			}
			output.write(buffer, 0, read);
		}
		return output.toByteArray();
	}

	private static byte channel(float value)
	{
		return (byte) Math.round(Math.max(0f, Math.min(1f, value)) * 255f);
	}

	private static int unsigned(byte value)
	{
		return value & 0xff;
	}

	private static JsonArray array(JsonObject object, String name)
	{
		JsonElement value = object == null ? null : object.get(name);
		return value != null && value.isJsonArray() ? value.getAsJsonArray() : null;
	}

	private static JsonObject object(JsonObject object, String name)
	{
		JsonElement value = object == null ? null : object.get(name);
		return value != null && value.isJsonObject() ? value.getAsJsonObject() : null;
	}

	private static int integer(JsonObject object, String name, int fallback)
	{
		JsonElement value = object == null ? null : object.get(name);
		return value == null || !value.isJsonPrimitive() ? fallback : value.getAsInt();
	}

	private static final class GlbReader
	{
		private final byte[] data;
		private final JsonObject document;
		private final int binaryOffset;
		private final int binaryLength;

		private GlbReader(byte[] data, JsonObject document, int binaryOffset, int binaryLength)
		{
			this.data = data;
			this.document = document;
			this.binaryOffset = binaryOffset;
			this.binaryLength = binaryLength;
		}

		private Accessor accessor(int accessorIndex) throws IOException
		{
			JsonArray accessors = array(document, "accessors");
			if (accessors == null || accessorIndex < 0 || accessorIndex >= accessors.size())
			{
				throw new IOException("Invalid binary glTF accessor");
			}
			JsonObject accessor = accessors.get(accessorIndex).getAsJsonObject();
			int count = integer(accessor, "count", -1);
			int components = components(accessor.has("type") ? accessor.get("type").getAsString() : "");
			int componentType = integer(accessor, "componentType", -1);
			int componentSize = componentSize(componentType);
			if (count < 0 || count > MAX_VERTICES * 3 || components < 1 || componentSize < 1)
			{
				throw new IOException("Invalid binary glTF accessor description");
			}

			float[] values = new float[count * components];
			int viewIndex = integer(accessor, "bufferView", -1);
			if (viewIndex < 0)
			{
				return new Accessor(values, components);
			}
			JsonArray views = array(document, "bufferViews");
			if (views == null || viewIndex >= views.size() || binaryOffset < 0)
			{
				throw new IOException("Invalid binary glTF buffer view");
			}
			JsonObject view = views.get(viewIndex).getAsJsonObject();
			int viewOffset = integer(view, "byteOffset", 0);
			int viewLength = integer(view, "byteLength", -1);
			int accessorOffset = integer(accessor, "byteOffset", 0);
			int stride = integer(view, "byteStride", components * componentSize);
			boolean normalized = accessor.has("normalized") && accessor.get("normalized").getAsBoolean();
			if (viewOffset < 0 || viewLength < 0 || accessorOffset < 0 || stride < components * componentSize)
			{
				throw new IOException("Invalid binary glTF buffer range");
			}
			long required = count == 0 ? 0L : (long) (count - 1) * stride + (long) components * componentSize;
			long relativeEnd = (long) viewOffset + accessorOffset + required;
			if (relativeEnd > binaryLength || accessorOffset + required > viewLength)
			{
				throw new IOException("Truncated binary glTF accessor");
			}

			ByteBuffer bytes = ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);
			int start = binaryOffset + viewOffset + accessorOffset;
			for (int index = 0; index < count; index++)
			{
				for (int component = 0; component < components; component++)
				{
					int at = start + index * stride + component * componentSize;
					values[index * components + component] = readComponent(bytes, at, componentType, normalized);
				}
			}
			return new Accessor(values, components);
		}
	}

	private static float readComponent(ByteBuffer buffer, int offset, int type, boolean normalized)
	{
		switch (type)
		{
			case 5120:
				return normalized ? Math.max(buffer.get(offset) / 127f, -1f) : buffer.get(offset);
			case 5121:
				return normalized ? (buffer.get(offset) & 0xff) / 255f : buffer.get(offset) & 0xff;
			case 5122:
				return normalized ? Math.max(buffer.getShort(offset) / 32767f, -1f) : buffer.getShort(offset);
			case 5123:
				return normalized ? (buffer.getShort(offset) & 0xffff) / 65535f : buffer.getShort(offset) & 0xffff;
			case 5125:
				long unsigned = buffer.getInt(offset) & 0xffffffffL;
				return unsigned;
			case 5126:
				return buffer.getFloat(offset);
			default:
				return 0f;
		}
	}

	private static int components(String type)
	{
		switch (type)
		{
			case "SCALAR": return 1;
			case "VEC2": return 2;
			case "VEC3": return 3;
			case "VEC4": return 4;
			default: return -1;
		}
	}

	private static int componentSize(int type)
	{
		switch (type)
		{
			case 5120:
			case 5121:
				return 1;
			case 5122:
			case 5123:
				return 2;
			case 5125:
			case 5126:
				return 4;
			default:
				return -1;
		}
	}

	private static final class Accessor
	{
		private final float[] values;
		private final int components;

		private Accessor(float[] values, int components)
		{
			this.values = values;
			this.components = components;
		}

		private int count()
		{
			return values.length / components;
		}
	}

	private static final class Mesh
	{
		private final float[] positions;
		private final byte[] colors;
		private final int[] indices;

		private Mesh(float[] positions, byte[] colors, int[] indices)
		{
			this.positions = positions;
			this.colors = colors;
			this.indices = indices;
		}
	}

	private static final class BodyFrame
	{
		private final float top;
		private final float headCenterX;

		private BodyFrame(float top, float headCenterX)
		{
			this.top = top;
			this.headCenterX = headCenterX;
		}
	}

	private static final class Run
	{
		private final float width;
		private final float middle;

		private Run(float width, float middle)
		{
			this.width = width;
			this.middle = middle;
		}
	}

	private static final class FloatBuilder
	{
		private float[] values = new float[1024];
		private int size;

		private void add(float value)
		{
			if (size == values.length)
			{
				values = Arrays.copyOf(values, values.length * 2);
			}
			values[size++] = value;
		}

		private int size()
		{
			return size;
		}

		private float[] toArray()
		{
			return Arrays.copyOf(values, size);
		}
	}

	private static final class ByteBuilder
	{
		private byte[] values = new byte[1024];
		private int size;

		private void add(byte value)
		{
			if (size == values.length)
			{
				values = Arrays.copyOf(values, values.length * 2);
			}
			values[size++] = value;
		}

		private byte[] toArray()
		{
			return Arrays.copyOf(values, size);
		}
	}

	private static final class IntBuilder
	{
		private int[] values = new int[1024];
		private int size;

		private void add(int value)
		{
			if (size == values.length)
			{
				values = Arrays.copyOf(values, values.length * 2);
			}
			values[size++] = value;
		}

		private int size()
		{
			return size;
		}

		private int[] toArray()
		{
			return Arrays.copyOf(values, size);
		}
	}
}

