package com.runedm;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.imageio.ImageIO;
import okhttp3.Call;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Loads RuneProfile character models and renders them locally as portraits.
 *
 * <p>No Discord, user-uploaded, or shared-server avatars are supported. A
 * missing RuneProfile model uses RuneProfile's bundled default player model.</p>
 */
final class AvatarService
{
	private static final Logger LOG = LoggerFactory.getLogger(AvatarService.class);
	private static final int AVATAR_SIZE = 96;
	private static final int MAX_RUNE_PROFILE_BYTES = 6 * 1024 * 1024;
	private static final long CACHE_MAX_AGE_MILLIS = 7L * 24L * 60L * 60L * 1000L;
	private static final long RETRY_MILLIS = 30_000L;
	private static final String CACHE_SUFFIX = "-front-v2.png";
	private static final HttpUrl RUNE_PROFILE_BASE_URL = HttpUrl.parse("https://www.runeprofile.com/");

	private final OkHttpClient httpClient;
	private final RuneDmConfig config;
	private final MessageStore messageStore;
	private final ExecutorService executor;
	private final Map<String, BufferedImage> avatarCache = new ConcurrentHashMap<>();
	private final Map<String, Long> retryAfter = new ConcurrentHashMap<>();
	private final Set<String> attempted = Collections.newSetFromMap(new ConcurrentHashMap<>());
	private final Set<Call> activeCalls = Collections.newSetFromMap(new ConcurrentHashMap<>());
	private final BufferedImage defaultAvatar =
		new BufferedImage(AVATAR_SIZE, AVATAR_SIZE, BufferedImage.TYPE_INT_ARGB);

	AvatarService(OkHttpClient httpClient, RuneDmConfig config, MessageStore messageStore)
	{
		this.httpClient = httpClient;
		this.config = config;
		this.messageStore = messageStore;
		this.executor = Executors.newSingleThreadExecutor(runnable ->
		{
			Thread thread = new Thread(runnable, "runedm-runeprofile");
			thread.setDaemon(true);
			return thread;
		});
	}

	BufferedImage getDefaultAvatar()
	{
		return defaultAvatar;
	}

	BufferedImage getMemoryAvatar(String playerName)
	{
		return avatarCache.getOrDefault(NameTools.avatarHash(playerName), defaultAvatar);
	}

	BufferedImage getOwnAvatar(String playerName)
	{
		return getMemoryAvatar(playerName);
	}

	void requestAvatar(String playerName, boolean ownAvatar, long accountHash, Runnable onChanged)
	{
		requestRuneProfileAvatar(playerName, onChanged);
	}

	void requestOwnAvatar(String playerName, long accountHash, Runnable onChanged)
	{
		requestRuneProfileAvatar(playerName, onChanged);
	}

	void requestRuneProfileAvatar(String playerName, Runnable onChanged)
	{
		String displayName = NameTools.displayName(playerName);
		if (displayName.isEmpty() || !config.runeProfileAvatars())
		{
			return;
		}

		String hash = NameTools.avatarHash(displayName);
		Long nextAttempt = retryAfter.get(hash);
		if (avatarCache.containsKey(hash)
			|| (nextAttempt != null && System.currentTimeMillis() < nextAttempt)
			|| !attempted.add(hash))
		{
			return;
		}

		executor.execute(() -> loadAvatar(displayName, hash, onChanged));
	}

	void resetRemoteAttempts()
	{
		avatarCache.clear();
		retryAfter.clear();
		attempted.clear();
	}

	static HttpUrl runeProfileModelUrl(String playerName)
	{
		String displayName = NameTools.displayName(playerName);
		return displayName.isEmpty() || RUNE_PROFILE_BASE_URL == null ? null : RUNE_PROFILE_BASE_URL.newBuilder()
			.addPathSegment("api")
			.addPathSegment("profiles")
			.addPathSegment("models")
			.addPathSegment(displayName)
			.build();
	}

	static HttpUrl runeProfileAvatarUrl(String playerName)
	{
		String displayName = NameTools.displayName(playerName);
		return displayName.isEmpty() || RUNE_PROFILE_BASE_URL == null ? null : RUNE_PROFILE_BASE_URL.newBuilder()
			.addPathSegment("og")
			.addPathSegment(displayName + ".png")
			.build();
	}

	static HttpUrl runeProfilePageUrl(String playerName)
	{
		String displayName = NameTools.displayName(playerName);
		return displayName.isEmpty() || RUNE_PROFILE_BASE_URL == null ? null : RUNE_PROFILE_BASE_URL.newBuilder()
			.addPathSegment(displayName)
			.build();
	}

	private void loadAvatar(String playerName, String hash, Runnable onChanged)
	{
		Path cachePath = messageStore.runeProfileAvatarCacheDirectory().resolve(hash + CACHE_SUFFIX);
		BufferedImage cached = readImage(cachePath);
		if (cached != null)
		{
			avatarCache.put(hash, cached);
			onChanged.run();
			if (!isExpired(cachePath))
			{
				attempted.remove(hash);
				return;
			}
		}

		HttpUrl modelUrl = runeProfileModelUrl(playerName);
		HttpUrl avatarUrl = runeProfileAvatarUrl(playerName);
		if (modelUrl == null || avatarUrl == null || !config.runeProfileAvatars())
		{
			finishAttempt(hash);
			return;
		}

		Call call = httpClient.newCall(new Request.Builder().url(modelUrl).get().build());
		activeCalls.add(call);
		try (Response response = call.execute())
		{
			if (response.code() == 404)
			{
				BufferedImage hostedDefault = downloadSocialHeadshot(avatarUrl);
				if (hostedDefault == null)
				{
					finishAttempt(hash);
					return;
				}
				cacheAvatar(hash, cachePath, hostedDefault, onChanged);
				return;
			}
			if (!response.isSuccessful() || !config.runeProfileAvatars())
			{
				finishAttempt(hash);
				return;
			}

			ResponseBody body = response.body();
			if (body == null || body.contentLength() > MAX_RUNE_PROFILE_BYTES)
			{
				finishAttempt(hash);
				return;
			}
			byte[] bytes;
			try (InputStream input = body.byteStream())
			{
				bytes = readLimited(input, MAX_RUNE_PROFILE_BYTES);
			}
			if (bytes == null)
			{
				finishAttempt(hash);
				return;
			}

			BufferedImage avatar;
			try
			{
				avatar = RuneProfileModelRenderer.renderHeadshot(bytes, AVATAR_SIZE);
			}
			catch (IOException | RuntimeException ex)
			{
				LOG.debug("Unable to render a RuneProfile model; using its social portrait", ex);
				avatar = downloadSocialHeadshot(avatarUrl);
			}
			if (avatar == null)
			{
				finishAttempt(hash);
				return;
			}
			cacheAvatar(hash, cachePath, avatar, onChanged);
		}
		catch (IOException ex)
		{
			LOG.debug("Direct Messages RuneProfile lookup failed", ex);
			finishAttempt(hash);
		}
		finally
		{
			activeCalls.remove(call);
		}
	}

	private BufferedImage downloadSocialHeadshot(HttpUrl avatarUrl) throws IOException
	{
		Call call = httpClient.newCall(new Request.Builder().url(avatarUrl).get().build());
		activeCalls.add(call);
		try (Response response = call.execute())
		{
			if (!response.isSuccessful())
			{
				return null;
			}
			ResponseBody body = response.body();
			if (body == null || body.contentLength() > MAX_RUNE_PROFILE_BYTES)
			{
				return null;
			}
			byte[] bytes;
			try (InputStream input = body.byteStream())
			{
				bytes = readLimited(input, MAX_RUNE_PROFILE_BYTES);
			}
			if (bytes == null)
			{
				return null;
			}
			BufferedImage downloaded;
			synchronized (ImageIO.class)
			{
				downloaded = ImageIO.read(new ByteArrayInputStream(bytes));
			}
			return downloaded == null ? null : runeProfileHeadshot(downloaded);
		}
		finally
		{
			activeCalls.remove(call);
		}
	}

	private static BufferedImage runeProfileHeadshot(BufferedImage source)
	{
		if (source.getWidth() < 64 || source.getHeight() < 64)
		{
			return null;
		}
		int cropSize = Math.max(1, Math.min((int) Math.round(source.getWidth() * 0.30), source.getHeight()));
		int headCenterX = (int) Math.round(source.getWidth() * 0.25);
		int cropX = Math.max(0, Math.min(headCenterX - cropSize / 2, source.getWidth() - cropSize));
		return UiImages.cropAndScale(source.getSubimage(cropX, 0, cropSize, cropSize), AVATAR_SIZE);
	}

	private void cacheAvatar(String hash, Path path, BufferedImage avatar, Runnable onChanged)
	{
		try
		{
			Files.createDirectories(path.getParent());
			writePngAtomically(avatar, path);
		}
		catch (IOException ex)
		{
			LOG.debug("Unable to cache a Direct Messages RuneProfile avatar", ex);
		}
		avatarCache.put(hash, avatar);
		retryAfter.remove(hash);
		attempted.remove(hash);
		onChanged.run();
	}

	private void finishAttempt(String hash)
	{
		retryAfter.put(hash, System.currentTimeMillis() + RETRY_MILLIS);
		attempted.remove(hash);
	}

	private static BufferedImage readImage(Path path)
	{
		if (!Files.isRegularFile(path))
		{
			return null;
		}
		try
		{
			return ImageIO.read(path.toFile());
		}
		catch (IOException ex)
		{
			return null;
		}
	}

	private static boolean isExpired(Path path)
	{
		try
		{
			return System.currentTimeMillis() - Files.getLastModifiedTime(path).toMillis() > CACHE_MAX_AGE_MILLIS;
		}
		catch (IOException ex)
		{
			return true;
		}
	}

	private static byte[] readLimited(InputStream input, int maximum) throws IOException
	{
		byte[] buffer = new byte[8192];
		java.io.ByteArrayOutputStream output = new java.io.ByteArrayOutputStream();
		int total = 0;
		int read;
		while ((read = input.read(buffer)) != -1)
		{
			total += read;
			if (total > maximum)
			{
				return null;
			}
			output.write(buffer, 0, read);
		}
		return output.toByteArray();
	}

	private static void writePngAtomically(BufferedImage image, Path target) throws IOException
	{
		Path temporary = target.resolveSibling(target.getFileName() + ".tmp");
		if (!ImageIO.write(image, "png", temporary.toFile()))
		{
			throw new IOException("No PNG image writer is available");
		}
		try
		{
			Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (AtomicMoveNotSupportedException ex)
		{
			Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	void close()
	{
		for (Call call : activeCalls)
		{
			call.cancel();
		}
		activeCalls.clear();
		executor.shutdownNow();
	}
}
